// (mismo patrón que sanctuaryRewardMul). Gated ⇒ OFF / sin juramento ⇒ 0. Puras (0 RNG, 0 estado, 0 side-effect).
function oathOrderOf(h){ if(!SANCTUARY_OATH.enabled||!h||!h.sanctuaryOath) return null;
  const O=SANCTUARY_OATH.orders||[]; for(let i=0;i<O.length;i++){ if(O[i].id===h.sanctuaryOath) return O[i]; } return null; }
function oathMul(h,kind){ const o=oathOrderOf(h); return (o && o.kind===kind) ? (+o.value||0) : 0; }
// tag corto de la orden jurada (o "") para el nameplate (capa social; reusa la ruta de TITLES). Puro, 0 sim/RNG.
export function sanctuaryOathTag(h){ const o=oathOrderOf(h||G.hero); return o?(o.tag||o.name||""):""; }
// CAS-2300: LIBRO DE LA ORDEN / ORDER LEDGER — progresión COLECTIVA semanal de la orden. Todo PURO (0 RNG, server-authority-ready).
// ledgerScheduleAt(nowMs) = ventana semanal derivada del reloj de pared (mirror emissaryScheduleAt): {period, into, frac, nextInSec}.
// Idéntica en todo cliente con el reloj correcto ⇒ marcador CONSISTENTE bajo N jugadores. Exportada para el harness de QA (prueba
// "mismo nowMs ⇒ mismo period/frac en N clientes"). Sólo tiene efecto observable bajo SANCTUARY_LEDGER.enabled.
export function ledgerScheduleAt(nowMs){
  const out={ enabled:!!SANCTUARY_LEDGER.enabled, period:0, into:0, frac:0, nextInSec:0 };
  if(!Number.isFinite(nowMs) || nowMs<=0) return out;             // sin reloj (harness sin nowMs) ⇒ inactivo, nada que derivar
  const periodMs=Math.max(1000,(SANCTUARY_LEDGER.periodSec|0)*1000);
  const elapsed=nowMs-(SANCTUARY_LEDGER.epochMs||0); if(elapsed<0) return out;
  const period=Math.floor(elapsed/periodMs), into=elapsed-period*periodMs;
  out.period=period>>>0; out.into=into; out.frac=into/periodMs; out.nextInSec=(periodMs-into)/1000;
  return out;
}
// baseline(period, orderId, frac) = contribución AGREGADA determinista del RESTO de la orden esa semana (0 RNG, hash de Knuth ⇒
// spread por orden), RAMPADA por `frac` (fracción de semana transcurrida) ⇒ la barra colectiva se llena a lo largo de la semana.
// En Stage-2 este baseline se sustituye por la SUMA real server-authoritative; el seam (total = baseline + mi contribución) no cambia.
function ledgerHash(period, orderId){ let s=((period>>>0)*2654435761)>>>0; const t=String(orderId||"");
  for(let i=0;i<t.length;i++){ s=(((s^t.charCodeAt(i))>>>0)*16777619)>>>0; } return s>>>0; }
function ledgerBaseline(period, orderId, frac){
  const g=Math.max(0,+SANCTUARY_LEDGER.goal||0);
  const jit=(+SANCTUARY_LEDGER.baselineJitter||0)*(((ledgerHash(period,orderId)%2001)/1000)-1);   // ±jitter determinista, 0 RNG
  const target=g*Math.max(0,(+SANCTUARY_LEDGER.baselineFrac||0)+jit);
  return Math.round(target*Math.max(0,Math.min(1,+frac||0)));      // rampa 0→target sobre la semana
}
// Contribución del jugador esta semana = DERIVADA de contadores MONÓTONOS ya vivos (h.kills + h.sanctuaryRep) MENOS el snapshot
// `base` tomado al rolar el period (h.ledgerAt). 0 tracking nuevo por-frame, 0 hook (misma técnica que Emissary/BOUNTY_BOARD).
function ledgerContribution(h){ if(!h||!h.ledgerAt) return 0;
  const dk=Math.max(0,(h.kills|0)-(h.ledgerAt.killBase|0));
  const dr=Math.max(0,(h.sanctuaryRep|0)-(h.ledgerAt.repBase|0));
  return Math.max(0, Math.round(dk*(+SANCTUARY_LEDGER.wKill||0) + dr*(+SANCTUARY_LEDGER.wRep||0))); }
// La orden del héroe la aporta el JURAMENTO (SANCTUARY_OATH). Sin juramento ⇒ null ⇒ no contribuye ni recibe pasivo.
function ledgerHeroOrder(h){ return (SANCTUARY_OATH.enabled && h && h.sanctuaryOath) ? String(h.sanctuaryOath) : null; }
function ledgerOrderDef(orderId){ const L=SANCTUARY_LEDGER.orders||[]; for(let i=0;i<L.length;i++){ if(L[i].id===orderId) return L[i]; } return null; }
// total(orden) = baseline(comunidad) + (¿es mi orden? mi contribución). Lee el schedule ya cacheado en G.ledger (reloj compartido).
function ledgerTotalFor(h, orderId){ const s=G.ledger; if(!s||!s.enabled) return 0;
  const base=ledgerBaseline(s.period, orderId, s.frac);
  const mine=(ledgerHeroOrder(h)===orderId) ? ledgerContribution(h) : 0;
  return base+mine; }
// ¿La orden del héroe CRUZÓ el umbral esta semana? ⇒ pasivo de orden activo. Gated ⇒ OFF / sin orden ⇒ false.
function ledgerUnlocked(h){ if(!SANCTUARY_LEDGER.enabled||!h) return false;
  const oid=ledgerHeroOrder(h); if(!oid) return false;
  return ledgerTotalFor(h,oid) >= Math.max(1,+SANCTUARY_LEDGER.goal||1); }
// ledgerMul(h,kind) = el `value` del pasivo de la orden del héroe si su kind coincide Y la orden está en racha, si no 0 ⇒ el knob
// reutilizado queda byte-idéntico a HEAD (mismo patrón que oathMul/sanctuaryRewardMul). Puro (0 RNG, 0 estado, 0 side-effect).
function ledgerMul(h,kind){ if(!ledgerUnlocked(h)) return 0; const d=ledgerOrderDef(ledgerHeroOrder(h)); return (d&&d.kind===kind)?(+d.value||0):0; }
// tick del LIBRO (mirror tickEmissary): deriva+cachea el schedule semanal del reloj COMPARTIDO (Date.now, leído SÓLO aquí y SÓLO
// bajo el gate) en G.ledger (transitorio, fuera del allowlist de serializeSave) y SNAPSHOTa el base per-semana en h.ledgerAt al rolar
// el period. OFF ⇒ NUNCA se invoca ⇒ Date.now nunca se llama, G.ledger/h.ledgerAt NUNCA se crean ⇒ byte-idéntico a HEAD.
function tickLedger(){ if(!SANCTUARY_LEDGER.enabled) return; const s=ledgerScheduleAt(Date.now()); G.ledger=s;
  const h=G.hero; if(!h||h.dead) return;
  if(!h.ledgerAt || (h.ledgerAt.period>>>0)!==(s.period>>>0)){    // period nuevo (o primera vez) ⇒ re-snapshot ⇒ contribución vuelve a 0
    h.ledgerAt={ period:s.period>>>0, killBase:h.kills|0, repBase:h.sanctuaryRep|0 }; } }        // el campo SÓLO se crea con la feature ON ⇒ byte-id OFF
// tag ★ (o "") de la orden EN RACHA para el nameplate (capa social; reusa la ruta de TITLES/Juramento). Puro, 0 sim/RNG.
export function sanctuaryLedgerTag(h){ h=h||G.hero; return ledgerUnlocked(h) ? "★" : ""; }
// View-model PURO para el panel del Tablón (el Libro de la Orden): la orden del héroe, su marcador colectivo, el umbral y el pasivo.
export function sanctuaryLedger(h){ h=h||G.hero; const s=G.ledger||null, oid=ledgerHeroOrder(h), o=oathOrderOf(h);
  const goal=Math.max(1,+SANCTUARY_LEDGER.goal||1), total=(s&&oid)?ledgerTotalFor(h,oid):0, def=ledgerOrderDef(oid);
  return { enabled:!!SANCTUARY_LEDGER.enabled, order:oid, orderName:o?(o.name||o.tag||oid):null, tag:o?(o.tag||""):"",
    goal, total, baseline:(s&&oid)?ledgerBaseline(s.period,oid,s.frac):0, contribution:h?ledgerContribution(h):0,
    frac:Math.max(0,Math.min(1,total/goal)), unlocked:ledgerUnlocked(h),
    passive:def?{ kind:def.kind, value:def.value }:null, nextInSec:s?(s.nextInSec|0):0 }; }

// CAS-2305: CLASIFICACIÓN DE ÓRDENES / ORDER STANDINGS — ranking SEMANAL COMPARTIDO de las 3 Órdenes por su BASELINE colectivo del
// Libro. Todo PURO (0 RNG, server-authority-ready). standingsRank(period,frac) = función PURA del reloj de pared ⇒ TODO cliente con el
// mismo reloj converge a la MISMA clasificación (idéntica en N jugadores, 0 desync). Usa SÓLO ledgerBaseline (la parte COMUNITARIA/
// server-authoritative), NUNCA la contribución per-hero (esa diverge por cliente ⇒ desync). Desempate ESTABLE por id (0 RNG). El ramp
// por frac es UNIFORME ⇒ el orden es estable toda la semana y depende sólo del jitter determinista por orden (rota por semana).
function standingsRank(period, frac){
  const orders=(SANCTUARY_LEDGER.orders||[]);
  const arr=orders.map(o=>({ id:o.id, total:ledgerBaseline(period, o.id, frac) }));
  arr.sort((a,b)=> (b.total-a.total) || (a.id<b.id?-1:(a.id>b.id?1:0)));   // desc por total colectivo; tie-break estable por id (0 RNG)
  for(let i=0;i<arr.length;i++) arr[i].rank=i+1;
  return { period:period>>>0, frac:Math.max(0,Math.min(1,+frac||0)), order:arr, leader:(arr[0]?arr[0].id:null) };
}
// La orden LÍDER de la clasificación cacheada esta semana (o null). Lee G.standings (derivado del reloj COMPARTIDO en tickStandings).
function standingsLeader(){ const s=G.standings; return s?s.leader:null; }
// standingsMul(h,kind) = el `leadValue` del pasivo del líder SÓLO si la orden del héroe (su Juramento) ES la líder Y el kind coincide,
// si no 0 ⇒ el knob de Descanso reutilizado queda byte-idéntico a HEAD (mismo patrón que ledgerMul/oathMul). Puro (0 RNG, 0 side-effect).
function standingsMul(h,kind){ if(!ORDER_STANDINGS.enabled||!h) return 0;
  if(kind!==(ORDER_STANDINGS.leadKind||"restedMult")) return 0;
  const oid=ledgerHeroOrder(h); if(!oid) return 0;
  return (standingsLeader()===oid) ? (+ORDER_STANDINGS.leadValue||0) : 0; }
// tick de la CLASIFICACIÓN (mirror tickLedger): deriva+cachea el ranking del reloj COMPARTIDO en G.standings (transitorio, fuera del
// allowlist de serializeSave ⇒ nunca persiste, 0 clave nueva). Reusa el period/frac YA derivado por tickLedger (G.ledger, misma
// ventana semanal); si aún no existe, deriva del reloj (Date.now leído SÓLO aquí y SÓLO bajo el gate). OFF ⇒ NUNCA se invoca ⇒
// G.standings NUNCA se crea, standingsMul RETURN 0 ⇒ byte-idéntico a HEAD.
function tickStandings(){ if(!ORDER_STANDINGS.enabled) return; const s=G.ledger||ledgerScheduleAt(Date.now()); G.standings=standingsRank(s.period, s.frac); }
// tag ♛ (o "") de la orden LÍDER para el nameplate del héroe (capa social; reusa la ruta de TITLES/Juramento). Puro, 0 sim/RNG.
export function sanctuaryStandingsTag(h){ h=h||G.hero; if(!ORDER_STANDINGS.enabled) return "";
  const oid=ledgerHeroOrder(h); return (oid && standingsLeader()===oid) ? "♛" : ""; }
// View-model PURO para el panel del Tablón (la Clasificación): las 3 Órdenes rankeadas + cuál es mi orden + si lidera + el pasivo.
export function orderStandings(h){ h=h||G.hero; const s=G.standings||null, mine=ledgerHeroOrder(h);
  return { enabled:!!ORDER_STANDINGS.enabled, leader:s?s.leader:null, mineOrder:mine,
    mineLeading:!!(mine && s && s.leader===mine), leadKind:ORDER_STANDINGS.leadKind||"restedMult", leadValue:+ORDER_STANDINGS.leadValue||0,
    order:s?s.order.map(o=>{ const def=oathOrderOf({sanctuaryOath:o.id}); return { id:o.id, rank:o.rank, total:o.total,
      name:def?(def.name||def.tag||o.id):o.id, tag:def?(def.tag||""):"", isLeader:s.leader===o.id, isMine:mine===o.id }; }):[] }; }

// CAS-2310: DOMINIO DE ÓRDENES / ORDER TERRITORY — control VISIBLE del Santuario por la orden LÍDER de la Clasificación. Todo DERIVADO
// (0 RNG, 0 estado nuevo, server-authority-ready). El CONTROLADOR = standingsLeader() (la orden líder ya cacheada en G.standings por
// tickStandings, DERIVADA del reloj COMPARTIDO) ⇒ TODO cliente con el mismo reloj converge al MISMO controlador (0 desync). OFF ⇒ null.
function territoryController(){ if(!ORDER_TERRITORY.enabled) return null; return contestController(standingsLeader()); }
// territoryMul(h,kind) = +controlValue SÓLO si: feature ON, kind coincide con controlKind, la orden del héroe (Juramento) ES la
// CONTROLADORA, Y el héroe está DENTRO de la Zona Segura (dominio ⇒ SÓLO en el territorio controlado). Guard de PRECEDENCIA: si controlKind
// coincide con el canal de ORDER_STANDINGS (leadKind), RETURN 0 (STANDINGS tiene precedencia ⇒ nunca se dobla el valor). Puro (0 RNG, 0
// side-effect) ⇒ OFF / fuera-de-zona / no-controlador ⇒ 0 ⇒ el knob safeRegen queda byte-idéntico a HEAD (mismo patrón que ledgerMul/standingsMul).
function territoryMul(h,kind){ if(!ORDER_TERRITORY.enabled||!h) return 0;
  if(kind!==(ORDER_TERRITORY.controlKind||"safeRegen")) return 0;
  if((ORDER_TERRITORY.controlKind||"safeRegen")===(ORDER_STANDINGS.leadKind||"restedMult")) return 0;   // precedencia: STANDINGS gana ⇒ no doblar
  const oid=ledgerHeroOrder(h); if(!oid) return 0;
  if(territoryController()!==oid) return 0;                        // sólo la orden CONTROLADORA
  return inSafeZone(h.x,h.y) ? (+ORDER_TERRITORY.controlValue||0) : 0; }   // SÓLO dentro de la zona controlada
// Estandarte de la orden CONTROLADORA para el badge de Zona Segura (capa social MMO — estado del MUNDO, mismo para todos en zona). Devuelve
// {order,name,tag} de la orden controladora (o null). Puro, 0 sim/RNG. OFF / sin controlador ⇒ null ⇒ nada se dibuja ⇒ byte-id.
export function territoryBanner(){ if(!ORDER_TERRITORY.enabled) return null; const oid=territoryController(); if(!oid) return null;
  const def=oathOrderOf({sanctuaryOath:oid}); return { order:oid, name:def?(def.name||def.tag||oid):oid, tag:def?(def.tag||""):"" }; }
// View-model PURO (panel/hook): el controlador del Santuario esta semana + si MI orden domina + el pasivo de zona (gateado a inSafeZone).
export function orderTerritory(h){ h=h||G.hero; const ctrl=territoryController(), mine=ledgerHeroOrder(h);
  return { enabled:!!ORDER_TERRITORY.enabled, controller:ctrl, mineOrder:mine, mineControls:!!(mine && ctrl && ctrl===mine),
    controlKind:ORDER_TERRITORY.controlKind||"safeRegen", controlValue:+ORDER_TERRITORY.controlValue||0,
    banner:territoryBanner(), inZone:h?inSafeZone(h.x,h.y):false,
    territoryMulSafeRegen:h?territoryMul(h,ORDER_TERRITORY.controlKind||"safeRegen"):0 }; }

// CAS-2313: ASALTO AL SANTUARIO / SANCTUARY CONTEST — ventana de asalto determinista donde el RETADOR (2º de la Clasificación) puede
// ARREBATAR el control del Santuario al líder. Todo DERIVADO (0 RNG, 0 estado nuevo, server-authority-ready): lee G.ledger (period/frac del
// reloj COMPARTIDO ya cacheado por tickLedger) + G.standings (ranking ya cacheado por tickStandings) ⇒ TODO cliente con el mismo reloj deriva
// la MISMA ventana, el MISMO surge y el MISMO flip en el MISMO tick lógico (convergencia N-clientes, 0 desync). NO añade tick/Date.now/G.* nuevo.
// OFF ⇒ contestController devuelve el líder SIN cambios ⇒ territoryController + banner + pasivo byte-idénticos a HEAD.
// contestWindow(frac) = tramo FINAL del ciclo semanal (windowFrac). active + iw(0→1) puramente del reloj compartido.
function contestWindow(frac){
  const wf=Math.max(0,Math.min(1,+ORDER_CONTEST.windowFrac||0));
  const start=1-wf, f=Math.max(0,Math.min(1,+frac||0)), active=wf>0 && f>=start;
  return { windowFrac:wf, start, active, iw: active ? Math.max(0,Math.min(1,(f-start)/wf)) : 0 };
}
// fuerza del asalto ESTA semana (determinista por period, 0 RNG) en banda [0.5,1.5): algunas semanas el surge basta para el flip, otras no
// (identidad social cambiante — territorio realmente disputado). Reusa ledgerHash (mismo hash de Knuth del Libro).
function contestStrength(period){ return 0.5 + (ledgerHash(period>>>0,"contest")%1000)/1000; }
// contestState() = snapshot AUTORITATIVO del asalto, derivado de G.standings (ranking) + G.ledger (ventana). Reglas: fuera de ventana el
// controlador (1º) RETIENE; en ventana el retador (2º) acumula `surge` (fracción de su baseline colectivo, rampada por iw × gain × fuerza)
// y si su total efectivo alcanza el baseline del controlador ⇒ flip STICKY (iw monótono ⇒ surge monótono) al retador. TODO baseline (0 per-hero).
function contestState(){
  const out={ enabled:!!ORDER_CONTEST.enabled, active:false, controller:null, challenger:null,
    controllerTotal:0, challengerTotal:0, surge:0, effective:null, flipped:false, progress:0, iw:0, windowFrac:0, nextInSec:0 };
  if(!ORDER_CONTEST.enabled) return out;
  const s=G.standings, L=G.ledger; if(!s||!s.order||s.order.length<2||!L) return out;
  const w=contestWindow(+L.frac||0); out.windowFrac=w.windowFrac; out.nextInSec=L.nextInSec|0;
  const ctrl=s.order[0].id, chal=s.order[1].id;
  out.controller=ctrl; out.challenger=chal; out.effective=ctrl;                 // por defecto (fuera de ventana / sin surge) el líder retiene
  out.controllerTotal=+s.order[0].total||0; out.challengerTotal=+s.order[1].total||0;
  if(!w.active) return out;
  out.active=true; out.iw=w.iw;
  out.surge=out.challengerTotal * (Math.max(0,+ORDER_CONTEST.gain||0)) * contestStrength(L.period>>>0) * w.iw;
  const chalEff=out.challengerTotal+out.surge;
  const holdThreshold=out.controllerTotal * (1 + Math.max(0,+ORDER_CONTEST.holdMargin||0));   // ventaja del defensor (incumbencia): hay que superar el umbral, no sólo empatar
  out.progress=holdThreshold>0 ? Math.max(0,Math.min(1, chalEff/holdThreshold)) : 0;
  if(chalEff>=holdThreshold && holdThreshold>0){ out.effective=chal; out.flipped=true; }
  return out;
}
// el controlador EFECTIVO del Santuario respetando el flip de asalto. OFF ⇒ devuelve `lead` SIN cambios (nunca evalúa contestState) ⇒
// territoryController byte-idéntico a HEAD. Server-auth: el flip lo decide esta función pura del reloj+ranking; el cliente sólo reconcilia.
function contestController(lead){ if(!ORDER_CONTEST.enabled) return lead;
  const c=contestState(); return (c.active && c.flipped) ? c.effective : lead; }
// Banner "Asalto en curso" para el badge de Zona segura (estado del MUNDO — mismo para todos en zona). {active,challengerTag,controllerTag,
// progress,flipped} o null (OFF / sin ventana). Puro, 0 sim/RNG. OFF ⇒ null ⇒ nada dibuja ⇒ byte-id.
export function contestBanner(){ if(!ORDER_CONTEST.enabled) return null; const c=contestState(); if(!c.active) return null;
  const cd=oathOrderOf({sanctuaryOath:c.challenger}), td=oathOrderOf({sanctuaryOath:c.controller});
  return { active:true, flipped:c.flipped, progress:c.progress,
    challenger:c.challenger, challengerTag:cd?(cd.tag||cd.name||c.challenger):c.challenger,
    controller:c.controller, controllerTag:td?(td.tag||td.name||c.controller):c.controller }; }
// View-model PURO (panel/hook): estado completo del asalto + el controlador EFECTIVO + si el flip está activo.
export function orderContest(h){ h=h||G.hero; const c=contestState(), mine=ledgerHeroOrder(h);
  return { enabled:!!ORDER_CONTEST.enabled, active:c.active, windowFrac:c.windowFrac, iw:+c.iw.toFixed(4), nextInSec:c.nextInSec,
    controller:c.controller, challenger:c.challenger, effective:c.effective, flipped:c.flipped,
    controllerTotal:c.controllerTotal, challengerTotal:c.challengerTotal, surge:+c.surge.toFixed(2), progress:+c.progress.toFixed(4),
    mineOrder:mine, mineChallenging:!!(mine && c.active && mine===c.challenger), mineControls:!!(mine && c.effective && mine===c.effective) }; }

// CAS-2316: COMPAÑEROS DE RUTA / WAYFARERS' FELLOWSHIP — capa social PERSONAL. Todo DERIVADO (0 RNG, server-authority-ready) e INDEPENDIENTE
// del arco de Órdenes (reloj + roster propios). fellowScheduleAt(nowMs) = ventana semanal derivada del reloj de pared COMPARTIDO (mirror
// ledgerScheduleAt, pero con periodSec/epochMs PROPIOS de FELLOWSHIP_BOND) ⇒ TODO cliente con el mismo reloj deriva el MISMO period/frac (banda
// CONSISTENTE bajo N jugadores, 0 desync). Exportada para el harness. Sólo tiene efecto observable bajo FELLOWSHIP_BOND.enabled.
export function fellowScheduleAt(nowMs){
  const out={ enabled:!!FELLOWSHIP_BOND.enabled, period:0, into:0, frac:0, nextInSec:0 };
  if(!Number.isFinite(nowMs) || nowMs<=0) return out;              // sin reloj (harness sin nowMs) ⇒ inactivo, nada que derivar
  const periodMs=Math.max(1000,(FELLOWSHIP_BOND.periodSec|0)*1000);
  const elapsed=nowMs-(FELLOWSHIP_BOND.epochMs||0); if(elapsed<0) return out;
  const period=Math.floor(elapsed/periodMs), into=elapsed-period*periodMs;
  out.period=period>>>0; out.into=into; out.frac=into/periodMs; out.nextInSec=(periodMs-into)/1000;
  return out;
}
// hash de Knuth por period (mismo mezclador determinista del Libro; salt para banda/rotación) ⇒ 0 RNG, spread estable.
function fellowHash(period, salt){ let s=((period>>>0)*2654435761)>>>0; const t=String(salt||"");
  for(let i=0;i<t.length;i++){ s=(((s^t.charCodeAt(i))>>>0)*16777619)>>>0; } return s>>>0; }
// La BANDA de esta semana = `size` compañeros ROTADOS del roster fijo por el reloj COMPARTIDO (start = hash(period)%N, consecutivos con wrap).
// Determinista (0 RNG) ⇒ TODO cliente con el mismo period ve la MISMA banda (convergente). Distintos por semana (rota) ⇒ identidad social viva.
function fellowRoster(period){
  const R=FELLOWSHIP_BOND.roster||[]; const N=R.length; if(N<=0) return [];
  const size=Math.max(0,Math.min(N,FELLOWSHIP_BOND.size|0)); if(size<=0) return [];
  const start=fellowHash(period>>>0,"fellow")%N; const out=[];
  for(let i=0;i<size;i++){ const m=R[(start+i)%N]; out.push({ id:String(m.id||""), name:String(m.name||m.id||"") }); }
  return out;
}
// Vínculo del héroe esta semana = DERIVADO del contador MONÓTONO `h.kills` MENOS el snapshot `base` tomado al rolar el period (h.fellowAt).
// 0 tracking nuevo por-frame, 0 hook (misma técnica que el Libro/Emisario). Sin snapshot (OFF / aún sin tick) ⇒ 0.
function fellowBond(h){ if(!h||!h.fellowAt) return 0;
  const dk=Math.max(0,(h.kills|0)-(h.fellowAt.killBase|0));
  return Math.max(0, Math.round(dk*(+FELLOWSHIP_BOND.bondPerKill||0))); }
// índice del TIER alcanzado por un bond dado (el tier más alto cuyo `at` ≤ bond). tiers ascendentes; el primero (at:0) es el base ⇒ siempre ≥0.
function fellowTierIdx(bond){ const T=FELLOWSHIP_BOND.tiers||[]; let idx=0;
  for(let i=0;i<T.length;i++){ if((bond|0)>=(+T[i].at||0)) idx=i; } return idx; }
// ¿La Hermandad está FORJADA? ⇒ el tier del bond alcanza forgeTier. Gated ⇒ OFF ⇒ false.
function fellowForged(h){ if(!FELLOWSHIP_BOND.enabled||!h) return false;
  return fellowTierIdx(fellowBond(h)) >= (FELLOWSHIP_BOND.forgeTier|0); }
// fellowMul(h,kind) = el `bondValue` del pasivo SÓLO si la Hermandad está FORJADA Y el kind coincide con bondKind, si no 0 ⇒ el seam reutilizado
// queda byte-idéntico a HEAD (mismo patrón que ledgerMul/standingsMul). Puro (0 RNG, 0 estado, 0 side-effect). kind ÚNICO ⇒ 0 doble-conteo.
function fellowMul(h,kind){ if(!fellowForged(h)) return 0;
  return (kind===(FELLOWSHIP_BOND.bondKind||"xpGain")) ? (+FELLOWSHIP_BOND.bondValue||0) : 0; }
// tick de la HERMANDAD (mirror tickLedger): deriva+cachea el schedule semanal del reloj COMPARTIDO (Date.now, leído SÓLO aquí y SÓLO bajo el
// gate) en G.fellowship (transitorio, fuera del allowlist de serializeSave) y SNAPSHOTa el base per-semana en h.fellowAt al rolar el period.
// OFF ⇒ NUNCA se invoca ⇒ Date.now nunca se llama, G.fellowship/h.fellowAt NUNCA se crean ⇒ byte-idéntico a HEAD.
function tickFellowship(){ if(!FELLOWSHIP_BOND.enabled) return; const s=fellowScheduleAt(Date.now()); G.fellowship=s;
  const h=G.hero; if(!h||h.dead) return;
  if(!h.fellowAt || (h.fellowAt.period>>>0)!==(s.period>>>0)){     // period nuevo (o primera vez) ⇒ re-snapshot ⇒ vínculo vuelve a 0
    h.fellowAt={ period:s.period>>>0, killBase:h.kills|0 }; } }    // el campo SÓLO se crea con la feature ON ⇒ byte-id OFF
// glifo ∞ (o "") para el nameplate cuando la Hermandad está FORJADA (capa social; reusa la ruta de Juramento/Libro/Clasificación). Puro, 0 sim/RNG.
export function fellowshipTag(h){ h=h||G.hero; return fellowForged(h) ? "∞" : ""; }
// View-model PURO para el panel del Tablón (los Compañeros de Ruta): la banda de esta semana, el vínculo, el tier alcanzado y el pasivo.
export function wayfarerFellowship(h){ h=h||G.hero; const s=G.fellowship||null;
  const bond=h?fellowBond(h):0, ti=fellowTierIdx(bond), T=FELLOWSHIP_BOND.tiers||[], forgeIdx=FELLOWSHIP_BOND.forgeTier|0;
  const nextTier=(ti+1<T.length)?T[ti+1]:null;
  return { enabled:!!FELLOWSHIP_BOND.enabled, periodSec:FELLOWSHIP_BOND.periodSec|0,
    band:s?fellowRoster(s.period):[], bond, tierIdx:ti, tierName:(T[ti]?T[ti].name:""),
    forged:h?fellowForged(h):false, forgeTierName:(T[forgeIdx]?T[forgeIdx].name:""),
    nextTierName:nextTier?nextTier.name:null, nextAt:nextTier?(+nextTier.at||0):null,
    bondKind:FELLOWSHIP_BOND.bondKind||"xpGain", bondValue:+FELLOWSHIP_BOND.bondValue||0,
    nextInSec:s?(s.nextInSec|0):0 }; }

// CAS-2322: VÍNCULO DE MENTOR / MENTORSHIP BOND — capa social ASIMÉTRICA (veterano↔novato). Todo DERIVADO (0 RNG, server-authority-ready), reloj
// PROPIO. mentorScheduleAt(nowMs) = ventana semanal del reloj de pared COMPARTIDO (mirror fellowScheduleAt con periodSec/epochMs PROPIOS de
// MENTOR_BOND) ⇒ TODO cliente con el mismo reloj deriva el MISMO period ⇒ MISMO compañero asignado (convergente, 0 desync). Exportada para el harness.
export function mentorScheduleAt(nowMs){
  const out={ enabled:!!MENTOR_BOND.enabled, period:0, into:0, frac:0, nextInSec:0 };
  if(!Number.isFinite(nowMs) || nowMs<=0) return out;
  const periodMs=Math.max(1000,(MENTOR_BOND.periodSec|0)*1000);
  const elapsed=nowMs-(MENTOR_BOND.epochMs||0); if(elapsed<0) return out;
  const period=Math.floor(elapsed/periodMs), into=elapsed-period*periodMs;
  out.period=period>>>0; out.into=into; out.frac=into/periodMs; out.nextInSec=(periodMs-into)/1000;
  return out;
}
// hash de Knuth por period (mismo mezclador determinista del Libro/Fellowship; salt PROPIO) ⇒ 0 RNG, asignación estable.
function mentorHash(period, salt){ let s=((period>>>0)*2654435761)>>>0; const t=String(salt||"");
  for(let i=0;i<t.length;i++){ s=(((s^t.charCodeAt(i))>>>0)*16777619)>>>0; } return s>>>0; }
// El COMPAÑERO asignado esta semana = 1 miembro del roster fijo elegido por el reloj COMPARTIDO (hash(period)%N). Determinista ⇒ TODO cliente con
// el mismo period ve el MISMO compañero (convergente). El ROL (mentor/protégé) lo decide el gap de nivel del héroe LOCAL vs este compañero.
function mentorPartner(period){
  const R=MENTOR_BOND.roster||[]; const N=R.length; if(N<=0) return null;
  const m=R[mentorHash(period>>>0,"mentor")%N];
  return { id:String(m.id||""), name:String(m.name||m.id||""), lvl:Math.max(1,(+m.lvl||1)) };
}
// gap de nivel del héroe vs el compañero asignado (heroLvl − partnerLvl). >0 ⇒ el héroe es el veterano; <0 ⇒ el héroe es el novato. Sin schedule ⇒ 0.
function mentorGap(h){ const s=G.mentor||null; if(!h||!s) return 0; const p=mentorPartner(s.period); if(!p) return 0;
  return (h.lvl|0)-(p.lvl|0); }
// ROL determinista por el gap con el UMBRAL: mentor si gap≥+thr, protégé si gap≤−thr, si no "none". Gated ⇒ OFF ⇒ "none".
function mentorRole(h){ if(!MENTOR_BOND.enabled||!h||!G.mentor) return "none";
  const thr=Math.max(1,(MENTOR_BOND.gapThreshold|0)), g=mentorGap(h);
  if(g>=thr) return "mentor"; if(g<=-thr) return "protege"; return "none"; }
// DWELL determinista de co-presencia = kills MONÓTONOS desde que se asignó el par (h.mentorAt), misma técnica que fellowBond/Libro (0 hook/frame).
function mentorDwell(h){ if(!h||!h.mentorAt) return 0;
  return Math.max(0,(h.kills|0)-(h.mentorAt.killBase|0)); }
// índice del TIER de dwell (el más alto cuyo `at`≤dwell). tiers ascendentes; el primero (at:0) es base ⇒ siempre ≥0.
function mentorTierIdx(dwell){ const T=MENTOR_BOND.tiers||[]; let idx=0;
  for(let i=0;i<T.length;i++){ if((dwell|0)>=(+T[i].at||0)) idx=i; } return idx; }
// ¿el par está LIGADO? ⇒ hay ROL (|gap|≥umbral) Y el dwell alcanza bindTier. Gated ⇒ OFF ⇒ false.
function mentorBound(h){ if(!MENTOR_BOND.enabled||!h) return false;
  if(mentorRole(h)==="none") return false;
  return mentorTierIdx(mentorDwell(h)) >= (MENTOR_BOND.bindTier|0); }
// boost de XP ESCALONADO del PROTÉGÉ = boost del tier de dwell alcanzado (sólo si LIGADO y rol protégé). El VETERANO NO recibe boost (sólo el título).
function mentorBoost(h){ if(!mentorBound(h) || mentorRole(h)!=="protege") return 0;
  const T=MENTOR_BOND.tiers||[], ti=mentorTierIdx(mentorDwell(h));
  return (+((T[ti]&&T[ti].boost)||0))||0; }
// mentorMul(h,kind) = el boost del PROTÉGÉ en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA anti-stacking que ESPEJA el patrón de
// EVOs previos (territoryMul→standingsMul): se de-stackea SÓLO en el MISMO canal. STANDINGS(colectivo) y MENTOR(personal) comparten restedMult ⇒ NO se
// suman: MENTOR CEDE (return 0) cuando STANDINGS ya aporta en ese canal ⇒ se aplica el MAYOR (el colectivo gana; standingsMul 0.15 ≥ mentorBoost máx 0.15).
// FELLOWSHIP(xpGain) y TERRITORY(safeRegen) son canales ⊥ ⇒ coexisten (igual que hoy fellowship-xpGain + standings-restedMult ya coexisten en gainXP;
// mismo precedente que territory-safeRegen coexiste con standings-restedMult). Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function mentorMul(h,kind){ if(!MENTOR_BOND.enabled||!h) return 0;
  if(kind!==(MENTOR_BOND.boostKind||"restedMult")) return 0;
  if(mentorRole(h)!=="protege" || !mentorBound(h)) return 0;
  if((MENTOR_BOND.boostKind||"restedMult")===(ORDER_STANDINGS.leadKind||"restedMult") && ORDER_STANDINGS.enabled && standingsMul(h,ORDER_STANDINGS.leadKind||"restedMult")>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana restedMult ⇒ MENTOR cede (aplica el MAYOR, 0 doble-conteo)
  return mentorBoost(h);
}
// tick del VÍNCULO (mirror tickFellowship): deriva+cachea el schedule semanal del reloj COMPARTIDO (Date.now, leído SÓLO aquí y SÓLO bajo el gate) en
// G.mentor (transitorio, fuera del allowlist de serializeSave) y SNAPSHOTa el base per-semana en h.mentorAt al rolar el period. OFF ⇒ NUNCA se invoca
// ⇒ Date.now nunca se llama, G.mentor/h.mentorAt NUNCA se crean ⇒ byte-idéntico a HEAD.
function tickMentor(){ if(!MENTOR_BOND.enabled) return; const s=mentorScheduleAt(Date.now()); G.mentor=s;
  const h=G.hero; if(!h||h.dead) return;
  if(!h.mentorAt || (h.mentorAt.period>>>0)!==(s.period>>>0)){     // period nuevo (o primera vez) ⇒ re-snapshot ⇒ dwell vuelve a 0
    h.mentorAt={ period:s.period>>>0, killBase:h.kills|0 }; } }    // el campo SÓLO se crea con la feature ON ⇒ byte-id OFF
// glifo del nameplate para el ROL LIGADO: ⚜ (mentor, honor) / ✦ (protégé, aprendiz) / "" si no ligado. Puro, 0 sim/RNG. Reusa la ruta de TITLES.
export function mentorBondTag(h){ h=h||G.hero; if(!mentorBound(h)) return "";
  return mentorRole(h)==="mentor" ? "⚜" : "✦"; }
// View-model PURO para el panel del Tablón: el compañero asignado, el rol, el gap, el dwell/tier y el boost del protégé.
export function mentorshipBond(h){ h=h||G.hero; const s=G.mentor||null, p=s?mentorPartner(s.period):null;
  const role=h?mentorRole(h):"none", dwell=h?mentorDwell(h):0, ti=mentorTierIdx(dwell), T=MENTOR_BOND.tiers||[];
  const nextTier=(ti+1<T.length)?T[ti+1]:null, bindIdx=MENTOR_BOND.bindTier|0;
  return { enabled:!!MENTOR_BOND.enabled, periodSec:MENTOR_BOND.periodSec|0, gapThreshold:MENTOR_BOND.gapThreshold|0,
    partner:p, role, gap:h?mentorGap(h):0, bound:h?mentorBound(h):false,
    dwell, tierIdx:ti, tierName:(T[ti]?T[ti].name:""), bindTierName:(T[bindIdx]?T[bindIdx].name:""),
    nextTierName:nextTier?nextTier.name:null, nextAt:nextTier?(+nextTier.at||0):null,
    boostKind:MENTOR_BOND.boostKind||"restedMult", boost:h?mentorBoost(h):0,
    mentorTitle:MENTOR_BOND.mentorTitle||"Mentor", protegeTitle:MENTOR_BOND.protegeTitle||"Protégé",
    nextInSec:s?(s.nextInSec|0):0 }; }

// CAS-2325: VESTIGIO DEL CAÍDO / FALLEN WAYFARER'S VESTIGE — el loop de MUERTE Y RECUPERACIÓN del mundo COMPARTIDO. Todo DERIVADO (0 RNG,
// server-authority-ready), reloj PROPIO. soulScheduleAt(nowMs) = ventana del reloj de pared COMPARTIDO (mirror mentor/fellowScheduleAt con
// periodSec/epochMs PROPIOS de SOUL_RECOVERY) ⇒ TODO cliente con el mismo reloj deriva el MISMO period ⇒ MISMO vestigio (convergente, 0 desync).
export function soulScheduleAt(nowMs){
  const out={ enabled:!!SOUL_RECOVERY.enabled, period:0, into:0, frac:0, nextInSec:0 };
  if(!Number.isFinite(nowMs) || nowMs<=0) return out;
  const periodMs=Math.max(1000,(SOUL_RECOVERY.periodSec|0)*1000);
  const elapsed=nowMs-(SOUL_RECOVERY.epochMs||0); if(elapsed<0) return out;
  const period=Math.floor(elapsed/periodMs), into=elapsed-period*periodMs;
  out.period=period>>>0; out.into=into; out.frac=into/periodMs; out.nextInSec=(periodMs-into)/1000;
  return out;
}
// hash de Knuth por period (mismo mezclador determinista del Libro/Fellowship/Mentor; salt PROPIO) ⇒ 0 RNG, elección estable.
function soulHash(period, salt){ let s=((period>>>0)*2654435761)>>>0; const t=String(salt||"");
  for(let i=0;i<t.length;i++){ s=(((s^t.charCodeAt(i))>>>0)*16777619)>>>0; } return s>>>0; }
// El CAÍDO de este period = 1 miembro del roster fijo elegido por el reloj COMPARTIDO (hash(period)%N). Determinista ⇒ TODO cliente con el mismo
// period ve el MISMO caído (convergente). Devuelve {idx,id,name}. Espeja mentorPartner/fellowRoster.
function soulFallen(period){
  const R=SOUL_RECOVERY.roster||[]; const N=R.length; if(N<=0) return null;
  const idx=soulHash(period>>>0,"fallen")%N, m=R[idx];
  return { idx, id:String(m.id||""), name:String(m.name||m.id||"") };
}
// La ZONA del vestigio de este period = 1 de SOUL_RECOVERY.zones elegida por hash. La TILE (posición mundo) se DERIVA del rect del PRIMER
// spawner de esa zona (0-draw, mirror bonfireSites) desplazada por una fracción hash-derivada ⇒ determinista, dentro de la zona de caza.
function soulZone(period){ const Z=SOUL_RECOVERY.zones||[]; if(!Z.length) return null; return Z[soulHash(period>>>0,"zone")%Z.length]; }
function soulPos(period, zone){
  const fx=(soulHash(period>>>0,"px")%1000)/1000, fy=(soulHash(period>>>0,"py")%1000)/1000;   // fracción determinista dentro del rect (0 RNG)
  // CAS-2326: elige el spawner de la zona cuya tile DERIVADA cae REALMENTE dentro de la zona (guard zoneOf, mirror bonfireSites/CAS-1886) —
  // los huntZones del continente (forest/ruins/caves) viven en `field`, así que el 1º s.zone===zone resolvía a `field` ⇒ soulInRadius (zone-gate)
  // nunca pasaba ⇒ vestigio IRRECUPERABLE. Determinista (0 RNG), orden de world.spawners. Sin spawner zone-consistente ⇒ null (ese period no tiene vestigio).
  for(const s of (world.spawners||[])){
    if(!s || !s.rect || s.zone!==zone) continue;
    const x=(s.rect.x+s.rect.w*(0.2+0.6*fx))*TS, y=(s.rect.y+s.rect.h*(0.2+0.6*fy))*TS;
    if(zoneOf(world,x,y)===zone) return { x, y, zone };
  }
  return null;
}
// ¿el vestigio del schedule está VIVO? ⇒ dentro de la fracción inicial liveFrac del period (luego CADUCA — limpieza determinista). Gated ⇒ OFF ⇒ false.
function soulLive(s){ if(!SOUL_RECOVERY.enabled || !s || !s.enabled) return false; return s.frac < Math.max(0,Math.min(1,+SOUL_RECOVERY.liveFrac||0)); }
// El VESTIGIO ambiental VIVO derivado del schedule (o null si caducó / OFF / sin posición). id = hash(period, fallen.id, zone) — espeja
// hash(playerId, deathTick, zoneId) del diseño. PURO (0 sim/RNG/side-effect). Exportado para render (glifo en la tile) y el harness.
export function soulVestige(s){ s=s||G.soul; if(!soulLive(s)) return null;
  const f=soulFallen(s.period), z=soulZone(s.period); if(!f||!z) return null; const pos=soulPos(s.period,z); if(!pos) return null;
  const id=soulHash(s.period>>>0, f.id+"|"+z)>>>0;
  return { id, period:s.period>>>0, fallen:f, zone:z, x:pos.x, y:pos.y, radius:Math.max(1,SOUL_RECOVERY.radius|0) }; }
// Identidad de WAYFARER del héroe LOCAL (mapea a un slot del roster de caídos). Por defecto DERIVADA de la clase (estable, 0 estado nuevo, 0 save);
// el harness puede fijar G.soulHeroIdx (transitorio) para observar ambos ROLES sin depender de la clase. Espeja el gap inyectable de mentor.
function soulHeroIdx(h){ const N=(SOUL_RECOVERY.roster||[]).length||1;
  if(G.soulHeroIdx!=null) return ((G.soulHeroIdx|0)%N+N)%N;
  return soulHash(0, String((h&&h.cls)||"warrior"))%N; }
// ROL determinista: si la identidad del héroe MAPEA al caído del period ⇒ "fallen" (es SU vestigio ⇒ no puede recuperar; buff de respawn). Si no
// ⇒ "recoverer". Gated ⇒ OFF / sin schedule ⇒ "none". Espeja mentorRole (rol por comparación local vs entidad compartida del reloj).
function soulRole(h){ if(!SOUL_RECOVERY.enabled||!h||!G.soul) return "none";
  const f=soulFallen(G.soul.period); if(!f) return "none";
  return soulHeroIdx(h)===f.idx ? "fallen" : "recoverer"; }
// ¿el héroe está en el radio del vestigio? dist² pura (0 RNG). El vestigio debe estar VIVO (soulVestige no-null) y en la zona del héroe.
function soulInRadius(h,v){ if(!h||!v) return false;
  if(zoneOf(world,h.x,h.y)!==v.zone) return false;
  return dist2(h.x,h.y,v.x,v.y) <= v.radius*v.radius; }
// DWELL de co-presencia acumulado (ms) para el vestigio v (0 si no está en radio con este id). Transitorio en h.soulAt (creado SÓLO ON ⇒ byte-id).
function soulDwellMs(h,v){ return (h&&h.soulAt&&v&&h.soulAt.vestigeId===v.id) ? Math.max(0,h.soulAt.dwellMs|0) : 0; }
// ¿el buff de respawn del CAÍDO sigue activo? ⇒ dentro de los primeros respawnKills kills tras dejar su vestigio (contador monótono, determinista,
// pin-independiente — mirror la técnica snapshot-kills de mentor/ledger). Gated ⇒ OFF ⇒ false.
function soulRespawnActive(h){ if(!SOUL_RECOVERY.enabled||!h||!h.soulFell) return false;
  return ((h.kills|0)-(h.soulFell.killBase|0)) < Math.max(0,SOUL_RECOVERY.respawnKills|0); }
// soulMul(h,kind) = el pasivo del RECUPERADOR (porta un vestigio recuperado este period) O del CAÍDO (buff de respawn), en el canal restedMult
// (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA anti-stacking (SOUL es la MÁS BAJA del canal): CEDE (return 0) a STANDINGS y a MENTOR ⇒ se aplica
// el MAYOR (0 doble-conteo; standings 0.15 / mentor 0.15 ≥ soul 0.10/0.15). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro. OFF ⇒ 0.
function soulMul(h,kind){ if(!SOUL_RECOVERY.enabled||!h) return 0;
  if(kind!==(SOUL_RECOVERY.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ SOUL cede
  if(mentorMul(h,kind)>0) return 0;      // precedencia MISMO-CANAL: MENTOR (personal) gana ⇒ SOUL cede
  const r=soulRole(h);
  if(r==="recoverer" && h.soulGot && G.soul && (h.soulGot.period>>>0)===(G.soul.period>>>0)) return +SOUL_RECOVERY.recovererBoost||0;   // porta el vestigio recuperado este period
  if(soulRespawnActive(h)) return +SOUL_RECOVERY.respawnBoost||0;   // caído: buff de recuperación en respawn (fade por kills)
  return 0;
}
// tryRecoverVestige() = el ÚNICO chokepoint de recuperación (mirror tryEmissary/tryPledgeOath). Valida rol≠fallen (no tu propio vestigio),
// vestigio VIVO, no-ya-recuperado este period, EN RADIO y DWELL≥umbral ⇒ elimina el vestigio ATÓMICAMENTE (server-auth first-come) y marca
// h.soulGot (⇒ activa el pasivo del recuperador). Devuelve {ok,reason,...}. Gated ⇒ OFF ⇒ {ok:false}.
function tryRecoverVestige(){
  if(!SOUL_RECOVERY.enabled) return { ok:false, reason:"disabled" };
  const h=G.hero, s=G.soul; if(!h||h.dead||!s) return { ok:false, reason:"nohero" };
  const v=soulVestige(s); if(!v) return { ok:false, reason:"expired" };
  if(soulRole(h)==="fallen") return { ok:false, reason:"own" };                                  // no puedes recuperar tu PROPIO vestigio
  if(h.soulGot && (h.soulGot.period>>>0)===(s.period>>>0)) return { ok:false, reason:"already" };
  if(!soulInRadius(h,v)) return { ok:false, reason:"far" };
  if(soulDwellMs(h,v) < Math.max(0,SOUL_RECOVERY.dwellSec|0)*1000) return { ok:false, reason:"dwell" };
  h.soulGot={ period:s.period>>>0, vestigeId:v.id>>>0 }; h.soulAt=null;                            // recupera ATÓMICAMENTE (el vestigio desaparece para este cliente)
  return { ok:true, vestigeId:v.id, fallen:v.fallen, zone:v.zone };
}
// tick del VESTIGIO (mirror tickMentor): deriva+cachea el schedule del reloj COMPARTIDO (Date.now, leído SÓLO aquí y SÓLO bajo el gate) en G.soul
// (transitorio, fuera del allowlist de serializeSave), acumula el DWELL de co-presencia del recuperador en radio (delta nowMs, frame-rate-indep) y
// auto-recupera al alcanzar el umbral (SIN hotkey). OFF ⇒ NUNCA se invoca ⇒ Date.now nunca se llama, G.soul/h.soulAt NUNCA se crean ⇒ byte-id.
// nowArg permite al harness inyectar el reloj (advance del dwell) sin tocar Date.now real.
function tickSoul(nowArg){ if(!SOUL_RECOVERY.enabled) return; const now=(nowArg!=null?+nowArg:Date.now());
  const s=soulScheduleAt(now); G.soul=s; const h=G.hero; if(!h||h.dead) return;
  const v=soulVestige(s);
  if(!v || soulRole(h)!=="recoverer" || (h.soulGot && (h.soulGot.period>>>0)===(s.period>>>0))){ if(h.soulAt) h.soulAt=null; return; }
  if(!soulInRadius(h,v)){ if(h.soulAt) h.soulAt=null; return; }                                   // salió del radio ⇒ resetea el dwell (sin fugas)
  if(!h.soulAt || h.soulAt.vestigeId!==v.id){ h.soulAt={ vestigeId:v.id>>>0, dwellMs:0, lastMs:now }; }   // entró: snapshot (SÓLO ON ⇒ byte-id)
  else { h.soulAt.dwellMs=(h.soulAt.dwellMs|0)+Math.max(0, now-(h.soulAt.lastMs|0)); h.soulAt.lastMs=now; }
  if(soulDwellMs(h,v) >= Math.max(0,SOUL_RECOVERY.dwellSec|0)*1000) tryRecoverVestige();          // auto-recupera al alcanzar el umbral (0 hotkey)
}
// glifo del VESTIGIO para el render sobre la tile: ⚱ (urna del caído) si hay vestigio VIVO. Puro, 0 sim/RNG. "" si OFF / caducó.
export function soulTag(s){ return soulVestige(s||G.soul) ? "⚱" : ""; }
// View-model PURO para el panel del Tablón: el vestigio ambiental, el rol del héroe, el dwell/umbral y el estado de recuperación/buff.
export function fallenVestige(h){ h=h||G.hero; const s=G.soul||null, v=soulVestige(s);
  const role=h?soulRole(h):"none", dwellMs=(h&&v)?soulDwellMs(h,v):0, dwellNeed=Math.max(0,SOUL_RECOVERY.dwellSec|0)*1000;
  const recovered=!!(h&&h.soulGot&&s&&(h.soulGot.period>>>0)===(s.period>>>0));
  return { enabled:!!SOUL_RECOVERY.enabled, periodSec:SOUL_RECOVERY.periodSec|0, radius:SOUL_RECOVERY.radius|0, dwellSec:SOUL_RECOVERY.dwellSec|0,
    vestige:v?{ id:v.id, fallen:v.fallen, zone:v.zone, x:+v.x.toFixed(2), y:+v.y.toFixed(2) }:null,
    role, dwellMs:dwellMs|0, dwellNeed, dwellFrac:dwellNeed>0?Math.min(1,dwellMs/dwellNeed):0,
    recovered, respawnActive:h?soulRespawnActive(h):false, nextInSec:s?(s.nextInSec|0):0 }; }

// CAS-2329: PULSO DEL MUNDO / WORLD PULSE — el PRIMER sistema de estado-de-mundo dinámico y AMBIENTAL (living-world). Todo DERIVADO (0 RNG,
// server-authority-ready), reloj PROPIO. pulseScheduleAt(nowMs) = ventana del reloj de pared COMPARTIDO (mirror soul/mentorScheduleAt con
// periodSec/epochMs PROPIOS de WORLD_PULSE) ⇒ TODO cliente con el mismo reloj deriva el MISMO period ⇒ MISMA zona-en-Pulso (convergente, 0 desync).
export function pulseScheduleAt(nowMs){
  const out={ enabled:!!WORLD_PULSE.enabled, period:0, into:0, frac:0, nextInSec:0 };
  if(!Number.isFinite(nowMs) || nowMs<=0) return out;
  const periodMs=Math.max(1000,(WORLD_PULSE.periodSec|0)*1000);
  const elapsed=nowMs-(WORLD_PULSE.epochMs||0); if(elapsed<0) return out;
  const period=Math.floor(elapsed/periodMs), into=elapsed-period*periodMs;
  out.period=period>>>0; out.into=into; out.frac=into/periodMs; out.nextInSec=(periodMs-into)/1000;
  return out;
}
// hash de Knuth por period (mismo mezclador determinista del Libro/Fellowship/Mentor/Vestigio; salt PROPIO) ⇒ 0 RNG, elección estable.
function pulseHash(period, salt){ let s=((period>>>0)*2654435761)>>>0; const t=String(salt||"");
  for(let i=0;i<t.length;i++){ s=(((s^t.charCodeAt(i))>>>0)*16777619)>>>0; } return s>>>0; }
// La zona EN PULSO de este period = 1 de WORLD_PULSE.zones elegida por hash (rotación determinista). Determinista ⇒ TODO cliente con el mismo period
// ve la MISMA zona (convergente). Espeja soulZone/mentorPartner. null si no hay zonas.
function pulseZone(period){ const Z=WORLD_PULSE.zones||[]; if(!Z.length) return null; return Z[pulseHash(period>>>0,"zone")%Z.length]; }
// ¿el pulso del schedule está VIVO? ⇒ dentro de la fracción inicial liveFrac del period (luego DECAE — limpieza determinista). Gated ⇒ OFF ⇒ false.
function pulseLive(s){ if(!WORLD_PULSE.enabled || !s || !s.enabled) return false; return s.frac < Math.max(0,Math.min(1,+WORLD_PULSE.liveFrac||0)); }
// La zona-en-Pulso VIVA derivada del schedule (o null si decayó / OFF / sin zonas). PURA (0 sim/RNG/side-effect). Exportada para render (banner) y el harness.
export function pulseZoneNow(s){ s=s||G.pulse; if(!pulseLive(s)) return null; return pulseZone(s.period); }
// pulseMul(h,kind) = el passive AMBIENTAL de los presentes en la zona-en-Pulso VIVA, en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA
// EXPLÍCITA anti-stacking (PULSE es la MÁS BAJA del canal): CEDE (return 0) a STANDINGS, MENTOR y SOUL ⇒ se aplica el MAYOR (0 doble-conteo).
// FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function pulseMul(h,kind){ if(!WORLD_PULSE.enabled||!h) return 0;
  if(kind!==(WORLD_PULSE.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ PULSE cede
  if(mentorMul(h,kind)>0) return 0;      // precedencia MISMO-CANAL: MENTOR (personal) gana ⇒ PULSE cede
  if(soulMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: SOUL (recuperación) gana ⇒ PULSE cede (es la MÁS BAJA del canal)
  const z=pulseZoneNow(G.pulse); if(!z) return 0;              // no hay pulso VIVO ⇒ 0
  if(zoneOf(world,h.x,h.y)!==z) return 0;                      // el héroe NO está físicamente en la zona-en-Pulso ⇒ 0
  return +WORLD_PULSE.boost||0;
}
// tick del PULSO (mirror tickMentor/tickSoul): deriva+cachea el schedule del reloj COMPARTIDO (Date.now, leído SÓLO aquí y SÓLO bajo el gate) en
// G.pulse (transitorio, fuera del allowlist de serializeSave). SIN estado per-hero, SIN dwell, SIN clave serializada. OFF ⇒ NUNCA se invoca ⇒
// Date.now nunca se llama, G.pulse NUNCA se crea ⇒ byte-id. nowArg permite al harness inyectar el reloj sin tocar Date.now real.
function tickPulse(nowArg){ if(!WORLD_PULSE.enabled) return; const now=(nowArg!=null?+nowArg:Date.now());
  G.pulse=pulseScheduleAt(now); }
// glifo del PULSO para el banner: ◈ (rombo de energía ambiental) si hay pulso VIVO. Puro, 0 sim/RNG. "" si OFF / decayó.
export function pulseTag(s){ return pulseZoneNow(s||G.pulse) ? "◈" : ""; }
// tile deterministic dentro de una zona (centro del 1er spawner zone-consistente, mirror soulPos/bonfireSites) — conveniencia de PRUEBA del harness. null si no hay.
function pulseSpot(zone){ for(const s of (world.spawners||[])){ if(!s||!s.rect||s.zone!==zone) continue;
  const x=(s.rect.x+s.rect.w*0.5)*TS, y=(s.rect.y+s.rect.h*0.5)*TS; if(zoneOf(world,x,y)===zone) return { x, y }; } return null; }
// View-model PURO para el HUD/panel: la zona-en-Pulso ambiental, si el héroe está en ella y su passive efectivo. 0 sim/RNG/side-effect.
export function worldPulse(h){ h=h||G.hero; const s=G.pulse||null; const zone=pulseZoneNow(s);
  const heroZone=h?zoneOf(world,h.x,h.y):null, inZone=!!(zone && heroZone===zone);
  return { enabled:!!WORLD_PULSE.enabled, periodSec:WORLD_PULSE.periodSec|0, liveFrac:+WORLD_PULSE.liveFrac,
    zone, live:(zone!=null), inZone, heroZone,
    frac: s?+(+s.frac).toFixed(4):0, nextInSec: s?(s.nextInSec|0):0,
    boostKind:WORLD_PULSE.channel||"restedMult", boost: h?pulseMul(h,WORLD_PULSE.channel||"restedMult"):0 }; }

// CAS-2332: CONGREGACIÓN / GATHERING DENSITY — la mecánica MÁS multiplayer-native del arco. La dirige el HEADCOUNT REAL de jugadores LIVE por zona
// (presencia server-authoritative), NO un reloj (World Pulse) NI un vínculo (Fellowship/Mentor/Soul). Todo DERIVADO del snapshot del server (0 RNG,
// server-authority-ready): el server empuja { zona → cuenta } y el cliente sólo lo REFLEJA (0 confianza; NO añade su propia presencia, el server ya la cuenta).
// congTier(count) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ count. Determinista, monótono, sin histéresis ⇒ sube/DECAE al cruzar umbral. OFF/sin tiers ⇒ 0.
function congTier(count){ const T=CONGREGATION.tiers||[]; count=count|0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && count>=(T[i].min|0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre congMul; aquí sólo la TABLA determinista.
function congBoost(count){ const t=congTier(count); return t>0 ? (+CONGREGATION.tiers[t-1].boost||0) : 0; }
// cuenta LIVE server-authoritative de una zona (del snapshot reflejado en G.congregation.counts). 0 si sin snapshot / zona ausente. Puro, 0 side-effect.
export function congCount(zone){ const g=G.congregation; if(!g||!g.counts||!zone) return 0; return g.counts[zone]|0; }
// congMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Congregación (tier≥1), en el canal restedMult (REUSA RESTED_XP), con
// PRECEDENCIA EXPLÍCITA anti-stacking (CONGREGATION es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL y PULSE ⇒ se
// aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function congMul(h,kind){ if(!CONGREGATION.enabled||!h) return 0;
  if(kind!==(CONGREGATION.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ CONGREGATION cede
  if(mentorMul(h,kind)>0) return 0;      // precedencia MISMO-CANAL: MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // precedencia MISMO-CANAL: PULSE (ambiental del reloj) gana ⇒ cede (CONGREGATION es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (CONGREGATION.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona congregable ⇒ 0
  return congBoost(congCount(z));        // el Δ del tier vigente por el headcount server-authoritative de esa zona
}
// tick de la CONGREGACIÓN (mirror tickPulse): REFLEJA el snapshot server-authoritative { zona → cuenta } (empujado por el server, cacheado en G.congServer)
// en G.congregation (transitorio, fuera del allowlist de serializeSave). SIN estado per-hero, SIN dwell, SIN clave serializada. OFF ⇒ NUNCA se invoca ⇒
// G.congregation/G.congServer NUNCA se crean ⇒ byte-id. En Stage-1 el harness/dev-hook empuja el snapshot (server-feed); en Stage-2 lo empuja el server real.
function tickCongregation(){ if(!CONGREGATION.enabled) return;
  const src=G.congServer||{}, counts={};
  for(const z of (CONGREGATION.zones||[])){ const n=src[z]|0; if(n>0) counts[z]=n; }   // valida a zonas congregables + descarta cuentas ≤0 (cliente sólo refleja)
  G.congregation={ counts }; }
// glifo de la Congregación para el badge (mirror pulseTag): ◈-cluster si la zona del héroe está en Congregación (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function congTag(h){ h=h||G.hero; if(!CONGREGATION.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(CONGREGATION.zones||[]).indexOf(z)<0) return ""; return congTier(congCount(z))>0 ? "⛭" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su cuenta LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function congregationVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const congable=!!(z && (CONGREGATION.zones||[]).indexOf(z)>=0);
  const count=congable?congCount(z):0, tier=congable?congTier(count):0;
  return { enabled:!!CONGREGATION.enabled, zone:z, congable, count, tier, tierCount:(CONGREGATION.tiers||[]).length,
    boostKind:CONGREGATION.channel||"restedMult", boost: h?congMul(h,CONGREGATION.channel||"restedMult"):0 }; }

// CAS-2335: SENDERO TRILLADO / WELL-TRODDEN PATH — EVO #52, pilar FRESCO de TRAVERSAL/logística EMERGENTE. El mundo COMPARTIDO se desgasta con el paso
// AGREGADO de MUCHOS jugadores A LO LARGO DEL TIEMPO: el server acumula "pisadas" por CELDA coarse (bucket de cellSize px, NO per-pixel), el tread DECAE
// determinista (vida-media, 0 RNG) y una celda cuyo tread ≥ threshold es un Sendero Trillado que da un pasivo restedMult a quien la transita. Todo
// DERIVADO del snapshot server-authoritative { celda → { tread, atMs } } (el cliente sólo REFLEJA) ⇒ 2 clientes con el mismo snapshot+reloj convergen byte-a-byte.
// clave COARSE de la celda que contiene (x,y) en px. Bucket de WAYFARER_TRAIL.cellSize px (NO per-pixel ⇒ mapa de senderos disperso, barato a escala). Puro, 0 side-effect.
function wayfarerCellKey(x,y){ const s=Math.max(1,(WAYFARER_TRAIL.cellSize|0)); return (Math.floor((+x||0)/s))+","+(Math.floor((+y||0)/s)); }
// tread DECAÍDO de la celda del héroe leído del snapshot reflejado en G.wayfarer.cells (ya decaído por tickWayfarer con el reloj compartido). 0 si sin snapshot / celda ausente. Puro.
function wayfarerTread(h){ const g=G.wayfarer; if(!g||!g.cells||!h) return 0; return +g.cells[wayfarerCellKey(h.x,h.y)]||0; }
// ¿la celda del héroe es un Sendero Trillado? (tread decaído ≥ threshold). Función pura del snapshot reflejado. 0-RNG, monótona con el tread.
function wayfarerTrodden(h){ return wayfarerTread(h) >= (+WAYFARER_TRAIL.threshold||0); }
// wayfarerMul(h,kind) = el pasivo COMPARTIDO de quien transita un Sendero Trillado, en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA
// anti-stacking (WAYFARER es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE y CONGREGATION ⇒ se aplica el MAYOR
// (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function wayfarerMul(h,kind){ if(!WAYFARER_TRAIL.enabled||!h) return 0;
  if(kind!==(WAYFARER_TRAIL.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ WAYFARER cede
  if(mentorMul(h,kind)>0) return 0;      // precedencia MISMO-CANAL: MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // precedencia MISMO-CANAL: PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: CONGREGATION (headcount) gana ⇒ cede (WAYFARER es la MÁS BAJA del canal)
  return wayfarerTrodden(h) ? (+WAYFARER_TRAIL.boost||0) : 0;   // el héroe transita un Sendero Trillado ⇒ el pasivo pequeño; si no, 0
}
// tick del SENDERO (mirror tickCongregation/tickPulse): REFLEJA el snapshot server-authoritative { celda → { tread, atMs } } (empujado por el server,
// cacheado en G.wayfarerServer) aplicando el DECAY determinista por vida-media (dec = tread·0.5^(max(0,now−atMs)/halfLife), 0 RNG) hacia G.wayfarer.cells
// (transitorio, fuera del allowlist de serializeSave). SIN estado per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca ⇒ Date.now nunca se llama,
// G.wayfarer/G.wayfarerServer NUNCA se crean ⇒ byte-id. nowArg permite al harness inyectar el reloj sin tocar Date.now real (prueba decay + convergencia).
function tickWayfarer(nowArg){ if(!WAYFARER_TRAIL.enabled) return; const now=(nowArg!=null?+nowArg:(G.wayfarerNow!=null?+G.wayfarerNow:Date.now()));   // fallback al reloj inyectado (dev/QA) para que el re-tick del game-loop no reintroduzca Date.now REAL entre frames y colapse el tread inyectado (footgun heredado pulse/mentor); en producción G.wayfarerNow es null ⇒ Date.now (correcto)
  const src=G.wayfarerServer||{}, cells={}, hl=Math.max(1,(WAYFARER_TRAIL.halfLifeSec|0))*1000;
  for(const k in src){ const e=src[k]; if(!e) continue; const raw=+e.tread||0, at=+e.atMs||0;
    const dec = at>0 ? raw*Math.pow(0.5, Math.max(0, now-at)/hl) : raw;   // decay determinista (sin RNG); elapsed<0 ⇒ sin decay (no crece hacia el futuro)
    if(dec>0) cells[k]=dec; }                                            // descarta celdas con tread ≤0 (cliente sólo refleja)
  G.wayfarer={ cells, nowMs:now }; }
// glifo del SENDERO para el badge (mirror congTag/pulseTag): ⌇ (traza sinuosa) si la celda del héroe es un Sendero Trillado. Puro, 0 sim/RNG. "" si OFF / no-trillada.
export function wayfarerTag(h){ h=h||G.hero; if(!WAYFARER_TRAIL.enabled||!h) return ""; return wayfarerTrodden(h) ? "⌇" : ""; }
// View-model PURO para el HUD/badge: la celda del héroe, su tread decaído server-authoritative, si es Sendero Trillado y su passive efectivo. 0 sim/RNG/side-effect.
export function wayfarerVM(h){ h=h||G.hero; const cell=h?wayfarerCellKey(h.x,h.y):null;
  const tread=h?wayfarerTread(h):0, trodden=h?wayfarerTrodden(h):false;
  return { enabled:!!WAYFARER_TRAIL.enabled, cell, tread:+tread.toFixed(3), trodden, threshold:+WAYFARER_TRAIL.threshold||0,
    boostKind:WAYFARER_TRAIL.channel||"restedMult", boost: h?wayfarerMul(h,WAYFARER_TRAIL.channel||"restedMult"):0 }; }

// CAS-2338: CONFLUENCIA / DIVERSE COMPANY — EVO #53, eje FRESCO de COMPOSICIÓN (variedad de clases co-presentes, NO headcount bruto como Congregación #51).
// El server cuenta la PRESENCIA por clase y zona y EMPUJA el snapshot { zona → { clase → cuenta } }; el cliente sólo lo REFLEJA. La DIVERSIDAD = nº de
// CLASES DISTINTAS con cuenta>0. Al cruzar umbrales (2/3/4 clases distintas) la zona entra en Confluencia por tiers y da a TODOS los presentes el MISMO
// passive (canal RESTED_XP). N clones de la MISMA clase (o 1 solo) NO abren nada. Todo DERIVADO del snapshot ⇒ 2 clientes con el mismo snapshot convergen byte-a-byte.
// confTier(nDistinct) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ diversidad. Determinista, monótono, sin histéresis ⇒ sube/DECAE al cruzar umbral. OFF/sin tiers ⇒ 0.
function confTier(nDistinct){ const T=DIVERSE_COMPANY.tiers||[]; nDistinct=nDistinct|0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && nDistinct>=(T[i].min|0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre confMul; aquí sólo la TABLA determinista.
function confBoost(nDistinct){ const t=confTier(nDistinct); return t>0 ? (+DIVERSE_COMPANY.tiers[t-1].boost||0) : 0; }
// roster { clase → cuenta } de una zona del snapshot reflejado en G.confluence.rosters. {} si sin snapshot / zona ausente. Puro, 0 side-effect.
function confRoster(zone){ const g=G.confluence; if(!g||!g.rosters||!zone) return {}; return g.rosters[zone]||{}; }
// DIVERSIDAD = nº de CLASES DISTINTAS co-presentes en la zona (variedad, NO suma de cabezas). Sólo clases con cuenta>0. Puro. 0 si sin snapshot / zona ausente.
export function confDiversity(zone){ const r=confRoster(zone); let n=0; for(const c in r){ if((r[c]|0)>0) n++; } return n; }
// confMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Confluencia (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA
// EXPLÍCITA anti-stacking (DIVERSE_COMPANY es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION y WAYFARER ⇒
// se aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function confMul(h,kind){ if(!DIVERSE_COMPANY.enabled||!h) return 0;
  if(kind!==(DIVERSE_COMPANY.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ CONFLUENCIA cede
  if(mentorMul(h,kind)>0) return 0;      // precedencia MISMO-CANAL: MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // precedencia MISMO-CANAL: PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // precedencia MISMO-CANAL: CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // precedencia MISMO-CANAL: WAYFARER (traversal) gana ⇒ cede (DIVERSE_COMPANY es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (DIVERSE_COMPANY.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona que pueda confluir ⇒ 0
  return confBoost(confDiversity(z));    // el Δ del tier vigente por el nº de clases distintas server-authoritative de esa zona
}
// tick de la CONFLUENCIA (mirror tickCongregation): REFLEJA el snapshot server-authoritative { zona → { clase → cuenta } } (empujado por el server, cacheado
// en G.confServer) en G.confluence (transitorio, fuera del allowlist de serializeSave). VALIDA a zonas confluibles + clases conocidas + descarta cuentas ≤0.
// SIN estado per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca ⇒ G.confluence/G.confServer NUNCA se crean ⇒ byte-id. En Stage-1 el harness/dev-hook empuja el snapshot.
function tickConfluence(){ if(!DIVERSE_COMPANY.enabled) return;
  const src=G.confServer||{}, rosters={}, valid=DIVERSE_COMPANY.classes||[];
  for(const z of (DIVERSE_COMPANY.zones||[])){ const raw=src[z]; if(!raw) continue; const r={};
    for(const c of valid){ const n=raw[c]|0; if(n>0) r[c]=n; }   // sólo clases conocidas con cuenta>0 (cliente sólo refleja; descarta clases inválidas y ≤0)
    if(Object.keys(r).length>0) rosters[z]=r; }
  G.confluence={ rosters }; }
// glifo de la Confluencia para el badge (mirror congTag/wayfarerTag): ❈ (estrella de corrientes que confluyen) si la zona del héroe está en Confluencia (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function confTag(h){ h=h||G.hero; if(!DIVERSE_COMPANY.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(DIVERSE_COMPANY.zones||[]).indexOf(z)<0) return ""; return confTier(confDiversity(z))>0 ? "❈" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su diversidad LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function confluenceVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const confable=!!(z && (DIVERSE_COMPANY.zones||[]).indexOf(z)>=0);
  const roster=confable?confRoster(z):{}, diversity=confable?confDiversity(z):0, tier=confable?confTier(diversity):0;
  return { enabled:!!DIVERSE_COMPANY.enabled, zone:z, confable, diversity, tier, tierCount:(DIVERSE_COMPANY.tiers||[]).length,
    classes:Object.keys(roster), roster:Object.assign({},roster),
    boostKind:DIVERSE_COMPANY.channel||"restedMult", boost: h?confMul(h,DIVERSE_COMPANY.channel||"restedMult"):0 }; }

// CAS-2341: VIGILIA / LONG WATCH — EVO #54, eje FRESCO de CONTINUIDAD TEMPORAL (cuánto lleva una zona OCUPADA SIN INTERRUPCIÓN por ≥1 jugador; NO headcount/footfall/
// composición/reloj). El server mantiene por zona un `streak` (segundos-ocupados-continuos) que SUBE con presencia y DECAE determinista al vaciarse (rompe si el hueco
// supera gapBreakSec), EMPUJA { zona → { streak, atMs, present } }; el cliente lo REFLEJA y lo PROYECTA al `now` compartido. Al cruzar umbrales (tiers) la zona entra en
// Vigilia y da a TODOS los presentes el MISMO passive (canal RESTED_XP). 1 jugador que entra y sale NO la abre. 2 clientes con el mismo snapshot+reloj convergen byte-a-byte.
// longWatchTier(streakSec) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ segundos-continuos. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function longWatchTier(streakSec){ const T=LONG_WATCH.tiers||[]; streakSec=+streakSec||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && streakSec>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre longWatchMul; aquí sólo la TABLA determinista.
function longWatchBoost(streakSec){ const t=longWatchTier(streakSec); return t>0 ? (+LONG_WATCH.tiers[t-1].boost||0) : 0; }
// streak PROYECTADO (segundos-ocupados-continuos) de una zona leído del snapshot reflejado en G.longWatch.streaks (ya proyectado al `now` por tickLongWatch). 0 si sin snapshot / zona ausente. Puro.
function longWatchStreak(zone){ const g=G.longWatch; if(!g||!g.streaks||!zone) return 0; return +g.streaks[zone]||0; }
function longWatchWatching(zone){ return longWatchTier(longWatchStreak(zone))>0; }
// longWatchMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Vigilia (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA
// anti-stacking (LONG_WATCH es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION, WAYFARER y DIVERSE_COMPANY ⇒ se
// aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function longWatchMul(h,kind){ if(!LONG_WATCH.enabled||!h) return 0;
  if(kind!==(LONG_WATCH.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ VIGILIA cede
  if(mentorMul(h,kind)>0) return 0;      // MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // WAYFARER (traversal) gana ⇒ cede
  if(confMul(h,kind)>0) return 0;        // DIVERSE_COMPANY (composición) gana ⇒ cede (LONG_WATCH es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (LONG_WATCH.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona que pueda vigilar ⇒ 0
  return longWatchBoost(longWatchStreak(z));   // el Δ del tier vigente por los segundos-continuos server-authoritative de esa zona
}
// tick de la VIGILIA (mirror tickWayfarer): REFLEJA el snapshot server-authoritative { zona → { streak, atMs, present } } (empujado por el server, cacheado en
// G.longWatchServer) y lo PROYECTA al `now` compartido hacia G.longWatch.streaks: present>0 ⇒ sube (min cap, streak+(now−atMs)); present==0 ⇒ ROMPE si el hueco supera
// gapBreakSec, si no DECAE por vida-media (0 RNG). SIN estado per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.longWatch/G.longWatchServer
// NUNCA se crean ⇒ byte-id. nowArg permite al harness inyectar el reloj sin tocar Date.now real (prueba subida/decay/ruptura + convergencia).
function tickLongWatch(nowArg){ if(!LONG_WATCH.enabled) return; const now=(nowArg!=null?+nowArg:(G.longWatchNow!=null?+G.longWatchNow:Date.now()));   // fallback al reloj inyectado (dev/QA) para que el re-tick del game-loop no reintroduzca Date.now REAL entre frames (footgun heredado wayfarer/pulse); en producción G.longWatchNow es null ⇒ Date.now
  const src=G.longWatchServer||{}, streaks={}, hl=Math.max(1,(LONG_WATCH.halfLifeSec|0))*1000, gap=Math.max(0,(LONG_WATCH.gapBreakSec|0))*1000, cap=Math.max(0,(LONG_WATCH.capSec|0));
  for(const z of (LONG_WATCH.zones||[])){ const raw=src[z]; if(!raw) continue;
    const base=Math.max(0,+raw.streak||0), atMs=+raw.atMs||0, present=(raw.present|0), dtMs=Math.max(0,now-atMs);
    let s;
    if(present>0){ s=base + dtMs/1000; if(cap>0) s=Math.min(cap,s); }   // ocupada ⇒ el streak SUBE con el tiempo transcurrido (techo cap)
    else if(dtMs>gap){ s=0; }                                          // hueco vacío > umbral ⇒ la vigilia se ROMPE
    else { s=base * Math.pow(0.5, dtMs/hl); }                          // vacía dentro del umbral ⇒ DECAE por vida-media
    if(s>0) streaks[z]=s; }
  G.longWatch={ streaks, nowMs:now }; }
// glifo de la Vigilia para el badge (mirror wayfarerTag/confTag): ⌖ (retícula de vigía) si la zona del héroe está en Vigilia (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function longWatchTag(h){ h=h||G.hero; if(!LONG_WATCH.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(LONG_WATCH.zones||[]).indexOf(z)<0) return ""; return longWatchWatching(z) ? "⌖" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su streak LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function longWatchVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const watchable=!!(z && (LONG_WATCH.zones||[]).indexOf(z)>=0);
  const streak=watchable?longWatchStreak(z):0, tier=watchable?longWatchTier(streak):0;
  return { enabled:!!LONG_WATCH.enabled, zone:z, watchable, streak:+streak.toFixed(2), tier, tierCount:(LONG_WATCH.tiers||[]).length,
    boostKind:LONG_WATCH.channel||"restedMult", boost: h?longWatchMul(h,LONG_WATCH.channel||"restedMult"):0 }; }

// CAS-2347: EXPEDICIÓN / FRONTIER SPREAD — EVO #55, pilar FRESCO de DISPERSIÓN ESPACIAL. Mide cuán ESPARCIDA está la comunidad en una zona (nº de SUB-CELDAS COARSE
// DISTINTAS ocupadas = cobertura/spread), ortogonal a headcount/footfall/composición/continuidad/reloj. server-authoritative: el server agrupa a los presentes en
// sub-celdas del MISMO grid coarse que Sendero, cuenta las distintas ocupadas, empuja { zona → { cover, atMs } }; el cliente REFLEJA + PROYECTA al `now` compartido con
// DECAY determinista (0 RNG). frontierCellKey(x,y) = clave COARSE de la sub-celda que contiene (x,y) en px (bucket FRONTIER_SPREAD.cellSize px, reuso del grid de Sendero). Puro.
function frontierCellKey(x,y){ const s=Math.max(1,(FRONTIER_SPREAD.cellSize|0)); return (Math.floor((+x||0)/s))+","+(Math.floor((+y||0)/s)); }
// frontierCoverage(occupants) = CÓMPUTO server-side de la cobertura = nº de SUB-CELDAS DISTINTAS ocupadas por un conjunto de posiciones [[x,y],...]. Función PURA (0 RNG,
// 0 side-effect). Casos borde: 1 pos ⇒ 1; N posiciones en la MISMA sub-celda ⇒ 1 (amontonarse NO cuenta — distingue de Congregación); N repartidas en K sub-celdas ⇒ K.
export function frontierCoverage(occupants){ if(!Array.isArray(occupants)||!occupants.length) return 0; const seen=Object.create(null); let n=0;
  for(const o of occupants){ if(!o) continue; const x=Array.isArray(o)?o[0]:o.x, y=Array.isArray(o)?o[1]:o.y; const k=frontierCellKey(x,y); if(!(k in seen)){ seen[k]=1; n++; } } return n; }
// frontierTier(cover) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ cover. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function frontierTier(cover){ const T=FRONTIER_SPREAD.tiers||[]; cover=+cover||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && cover>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre frontierMul; aquí sólo la TABLA determinista.
function frontierBoost(cover){ const t=frontierTier(cover); return t>0 ? (+FRONTIER_SPREAD.tiers[t-1].boost||0) : 0; }
// cobertura PROYECTADA (sub-celdas distintas ocupadas) de una zona leída del snapshot reflejado en G.frontier.cover (ya proyectada al `now` por tickFrontier). 0 si sin snapshot / zona ausente. Puro.
function frontierCover(zone){ const g=G.frontier; if(!g||!g.cover||!zone) return 0; return +g.cover[zone]||0; }
function frontierOpen(zone){ return frontierTier(frontierCover(zone))>0; }
// frontierMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Expedición (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA
// anti-stacking (FRONTIER_SPREAD es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION, WAYFARER, DIVERSE_COMPANY y
// LONG_WATCH ⇒ se aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function frontierMul(h,kind){ if(!FRONTIER_SPREAD.enabled||!h) return 0;
  if(kind!==(FRONTIER_SPREAD.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ EXPEDICIÓN cede
  if(mentorMul(h,kind)>0) return 0;      // MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // WAYFARER (traversal) gana ⇒ cede
  if(confMul(h,kind)>0) return 0;        // DIVERSE_COMPANY (composición) gana ⇒ cede
  if(longWatchMul(h,kind)>0) return 0;   // LONG_WATCH (continuidad) gana ⇒ cede (FRONTIER_SPREAD es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (FRONTIER_SPREAD.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona de frontera ⇒ 0
  return frontierBoost(frontierCover(z));   // el Δ del tier vigente por la cobertura server-authoritative de esa zona
}
// tick de la EXPEDICIÓN (mirror tickWayfarer/tickLongWatch): REFLEJA el snapshot server-authoritative { zona → { cover, atMs } } (empujado por el server, cacheado en
// G.frontierServer) y lo PROYECTA al `now` compartido hacia G.frontier.cover aplicando el DECAY determinista por vida-media (cover_now = cover·0.5^(max(0,now−atMs)/halfLife),
// 0 RNG, techo capCover). SIN estado per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.frontier/G.frontierServer NUNCA se crean ⇒ byte-id.
// nowArg permite al harness inyectar el reloj sin tocar Date.now real (prueba decay + convergencia). Fallback al reloj inyectado (G.frontierNow) para que el re-tick del
// game-loop no reintroduzca Date.now REAL entre frames y colapse la cobertura inyectada (footgun heredado wayfarer/longWatch); en producción G.frontierNow es null ⇒ Date.now.
function tickFrontier(nowArg){ if(!FRONTIER_SPREAD.enabled) return; const now=(nowArg!=null?+nowArg:(G.frontierNow!=null?+G.frontierNow:Date.now()));
  const src=G.frontierServer||{}, cover={}, hl=Math.max(1,(FRONTIER_SPREAD.halfLifeSec|0))*1000, cap=Math.max(0,(FRONTIER_SPREAD.capCover|0));
  for(const z of (FRONTIER_SPREAD.zones||[])){ const raw=src[z]; if(!raw) continue;
    const base=Math.max(0,+raw.cover||0), atMs=+raw.atMs||0, dtMs=Math.max(0,now-atMs);
    let c=base * Math.pow(0.5, dtMs/hl); if(cap>0) c=Math.min(cap,c);   // DECAE determinista por vida-media hacia el `now` compartido (0 RNG)
    if(c>0) cover[z]=c; }
  G.frontier={ cover, nowMs:now }; }
// glifo de la Expedición para el badge (mirror longWatchTag/confTag): ⌗ (malla de sub-celdas cubiertas) si la zona del héroe está en Expedición (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function frontierTag(h){ h=h||G.hero; if(!FRONTIER_SPREAD.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(FRONTIER_SPREAD.zones||[]).indexOf(z)<0) return ""; return frontierOpen(z) ? "⌗" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su cobertura LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function frontierVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const frontierable=!!(z && (FRONTIER_SPREAD.zones||[]).indexOf(z)>=0);
  const cover=frontierable?frontierCover(z):0, tier=frontierable?frontierTier(cover):0;
  return { enabled:!!FRONTIER_SPREAD.enabled, zone:z, frontierable, cover:+cover.toFixed(2), tier, tierCount:(FRONTIER_SPREAD.tiers||[]).length,
    boostKind:FRONTIER_SPREAD.channel||"restedMult", boost: h?frontierMul(h,FRONTIER_SPREAD.channel||"restedMult"):0 }; }

// CAS-2352: AFLUENCIA / INFLUX SURGE — EVO #56, pilar FRESCO de TASA DE LLEGADA (flujo/afluencia). Mide el RITMO de ENTRADAS (jugadores nuevos que CRUZAN hacia una zona),
// ortogonal a headcount/footfall/composición/continuidad/dispersión/reloj. server-authoritative: el server detecta las LLEGADAS (transición de borde fuera→dentro), las
// acumula en un `surge` con DECAY (0 RNG), empuja { zona → { surge, atMs } }; el cliente REFLEJA + PROYECTA al `now` compartido. influxArrivals(prevIds,nowIds) = CÓMPUTO
// server-side de las llegadas = nº de ids DENTRO AHORA que NO estaban antes (EDGE-triggered). Función PURA (0 RNG, 0 side-effect). Casos borde: prev==now (misma multitud quieta)
// ⇒ 0 (amontonarse/quedarse NO cuenta — distingue de Congregación, que SÍ abre por headcount); todos nuevos ⇒ |now| (oleada de recién-llegados abre).
export function influxArrivals(prevIds,nowIds){ if(!Array.isArray(nowIds)||!nowIds.length) return 0; const was=Object.create(null);
  if(Array.isArray(prevIds)) for(const p of prevIds){ if(p!=null) was[String(p)]=1; } let n=0; const seen=Object.create(null);
  for(const q of nowIds){ if(q==null) continue; const k=String(q); if(k in seen) continue; seen[k]=1; if(!(k in was)) n++; } return n; }
// influxTier(surge) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ surge. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function influxTier(surge){ const T=INFLUX_SURGE.tiers||[]; surge=+surge||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && surge>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre influxMul; aquí sólo la TABLA determinista.
function influxBoost(surge){ const t=influxTier(surge); return t>0 ? (+INFLUX_SURGE.tiers[t-1].boost||0) : 0; }
// surge PROYECTADO (llegadas acumuladas) de una zona leído del snapshot reflejado en G.influx.surge (ya proyectado al `now` por tickInflux). 0 si sin snapshot / zona ausente. Puro.
function influxSurgeVal(zone){ const g=G.influx; if(!g||!g.surge||!zone) return 0; return +g.surge[zone]||0; }
function influxOpen(zone){ return influxTier(influxSurgeVal(zone))>0; }
// influxMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Afluencia (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA anti-stacking
// (INFLUX_SURGE es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION, WAYFARER, DIVERSE_COMPANY, LONG_WATCH y FRONTIER_SPREAD
// ⇒ se aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function influxMul(h,kind){ if(!INFLUX_SURGE.enabled||!h) return 0;
  if(kind!==(INFLUX_SURGE.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ AFLUENCIA cede
  if(mentorMul(h,kind)>0) return 0;      // MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // WAYFARER (traversal) gana ⇒ cede
  if(confMul(h,kind)>0) return 0;        // DIVERSE_COMPANY (composición) gana ⇒ cede
  if(longWatchMul(h,kind)>0) return 0;   // LONG_WATCH (continuidad) gana ⇒ cede
  if(frontierMul(h,kind)>0) return 0;    // FRONTIER_SPREAD (dispersión) gana ⇒ cede (INFLUX_SURGE es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (INFLUX_SURGE.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona de afluencia ⇒ 0
  return influxBoost(influxSurgeVal(z));   // el Δ del tier vigente por el surge server-authoritative de esa zona
}
// tick de la AFLUENCIA (mirror tickFrontier/tickLongWatch): REFLEJA el snapshot server-authoritative { zona → { surge, atMs } } (empujado por el server, cacheado en
// G.influxServer) y lo PROYECTA al `now` compartido hacia G.influx.surge aplicando el DECAY determinista por vida-media (surge_now = surge·0.5^(max(0,now−atMs)/halfLife),
// 0 RNG, techo capSurge). SIN estado per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.influx/G.influxServer NUNCA se crean ⇒ byte-id.
// nowArg permite al harness inyectar el reloj sin tocar Date.now real (prueba decay + convergencia). Fallback al reloj inyectado (G.influxNow) para que el re-tick del
// game-loop no reintroduzca Date.now REAL entre frames y colapse el surge inyectado (footgun heredado frontier/longWatch); en producción G.influxNow es null ⇒ Date.now.
function tickInflux(nowArg){ if(!INFLUX_SURGE.enabled) return; const now=(nowArg!=null?+nowArg:(G.influxNow!=null?+G.influxNow:Date.now()));
  const src=G.influxServer||{}, surge={}, hl=Math.max(1,(INFLUX_SURGE.halfLifeSec|0))*1000, cap=Math.max(0,(INFLUX_SURGE.capSurge|0));
  for(const z of (INFLUX_SURGE.zones||[])){ const raw=src[z]; if(!raw) continue;
    const base=Math.max(0,+raw.surge||0), atMs=+raw.atMs||0, dtMs=Math.max(0,now-atMs);
    let s=base * Math.pow(0.5, dtMs/hl); if(cap>0) s=Math.min(cap,s);   // DECAE determinista por vida-media hacia el `now` compartido (0 RNG)
    if(s>0) surge[z]=s; }
  G.influx={ surge, nowMs:now }; }
// helper server-side: registra `n` LLEGADAS en una zona ACUMULANDO sobre el surge proyectado al `atMs` (mirror del acumulador con decay). Puro sobre G.influxServer; devuelve el nuevo raw.
function influxAccrue(zone, n, atMs){ if((INFLUX_SURGE.zones||[]).indexOf(zone)<0) return null; n=Math.max(0,+n||0);
  const src=G.influxServer||(G.influxServer={}), raw=src[zone], hl=Math.max(1,(INFLUX_SURGE.halfLifeSec|0))*1000;
  const prevBase=raw?Math.max(0,+raw.surge||0):0, prevAt=raw?(+raw.atMs||0):atMs, dtMs=Math.max(0,atMs-prevAt);
  const projected=prevBase*Math.pow(0.5, dtMs/hl);   // proyecta el surge previo al instante de esta llegada
  src[zone]={ surge:projected+n, atMs }; return src[zone]; }
// glifo de la Afluencia para el badge (mirror frontierTag/longWatchTag): ⇈ (flechas de entrada ascendentes) si la zona del héroe está en Afluencia (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function influxTag(h){ h=h||G.hero; if(!INFLUX_SURGE.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(INFLUX_SURGE.zones||[]).indexOf(z)<0) return ""; return influxOpen(z) ? "⇈" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su surge LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function influxVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const influxable=!!(z && (INFLUX_SURGE.zones||[]).indexOf(z)>=0);
  const surge=influxable?influxSurgeVal(z):0, tier=influxable?influxTier(surge):0;
  return { enabled:!!INFLUX_SURGE.enabled, zone:z, influxable, surge:+surge.toFixed(2), tier, tierCount:(INFLUX_SURGE.tiers||[]).length,
    boostKind:INFLUX_SURGE.channel||"restedMult", boost: h?influxMul(h,INFLUX_SURGE.channel||"restedMult"):0 }; }

// CAS-2355: SINCRONÍA DE BATALLA / BATTLE SYNCHRONY — EVO #57, pilar FRESCO de CORRELACIÓN / SIMULTANEIDAD de gestas de combate. Mide la CO-OCURRENCIA temporal de kills entre jugadores
// DISTINTOS co-presentes, ortogonal a headcount/footfall/composición/continuidad/dispersión/flujo/reloj/nivel. server-authoritative: el server marca el instante de la ÚLTIMA gesta (kill,
// REUSA el contador monótono h.kills) de cada jugador por zona, empuja { zona → { id → últimoKillMs } }; el cliente REFLEJA + PROYECTA al `now` compartido. syncCount(marks,now,windowMs) =
// CÓMPUTO server-side de la sincronía = nº de ids DISTINTOS cuya última gesta cae DENTRO de la ventana deslizante [now−windowMs, now]. Función PURA (0 RNG, 0 side-effect). Casos borde:
// N presentes pero INACTIVOS (sin marca / kills viejos) ⇒ 0 (amontonarse/estar NO cuenta — distingue de Congregación por headcount y de Afluencia por flujo); 2 en ventanas separadas
// ⇒ en cualquier `now` sólo 1 cae en la ventana ⇒ 0 (es CORRELACIÓN temporal, no un rate acumulado); 1 solo matando ⇒ 1 (NO abre — requiere ≥2 DISTINTOS); todos matando a la vez ⇒ |ids|.
export function syncCount(marks, now, windowMs){ if(!marks || typeof marks!=="object") return 0; now=+now||0; windowMs=Math.max(0,+windowMs||0);
  let n=0; for(const id in marks){ const t=+marks[id]; if(!isFinite(t)) continue; const dt=now-t; if(dt>=0 && dt<=windowMs) n++; } return n; }
// syncTier(count) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ count. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function syncTier(count){ const T=BATTLE_SYNC.tiers||[]; count=+count||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && count>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre syncMul; aquí sólo la TABLA determinista.
function syncBoost(count){ const t=syncTier(count); return t>0 ? (+BATTLE_SYNC.tiers[t-1].boost||0) : 0; }
// nº de jugadores sincronizados PROYECTADO de una zona leído del snapshot reflejado en G.sync.count (ya proyectado al `now` por tickBattleSync). 0 si sin snapshot / zona ausente. Puro.
function syncCountVal(zone){ const g=G.sync; if(!g||!g.count||!zone) return 0; return +g.count[zone]||0; }
function syncOpen(zone){ return syncTier(syncCountVal(zone))>0; }
// syncMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Sincronía (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA anti-stacking
// (BATTLE_SYNC es la MÁS BAJA del canal ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION, WAYFARER, DIVERSE_COMPANY, LONG_WATCH, FRONTIER_SPREAD e INFLUX_SURGE
// ⇒ se aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function syncMul(h,kind){ if(!BATTLE_SYNC.enabled||!h) return 0;
  if(kind!==(BATTLE_SYNC.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ SINCRONÍA cede
  if(mentorMul(h,kind)>0) return 0;      // MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // WAYFARER (traversal) gana ⇒ cede
  if(confMul(h,kind)>0) return 0;        // DIVERSE_COMPANY (composición) gana ⇒ cede
  if(longWatchMul(h,kind)>0) return 0;   // LONG_WATCH (continuidad) gana ⇒ cede
  if(frontierMul(h,kind)>0) return 0;    // FRONTIER_SPREAD (dispersión) gana ⇒ cede
  if(influxMul(h,kind)>0) return 0;      // INFLUX_SURGE (afluencia) gana ⇒ cede (BATTLE_SYNC es la MÁS BAJA del canal)
  const z=zoneOf(world,h.x,h.y); if(!z || (BATTLE_SYNC.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona de sincronía ⇒ 0
  return syncBoost(syncCountVal(z));   // el Δ del tier vigente por el nº de sincronizados server-authoritative de esa zona
}
// tick de la SINCRONÍA (mirror tickInflux/tickFrontier): REFLEJA el snapshot server-authoritative { zona → { id → últimoKillMs } } (empujado por el server, cacheado en
// G.syncServer) y lo PROYECTA al `now` compartido hacia G.sync.count contando cuántos ids DISTINTOS caen en la ventana deslizante (0 RNG). SIN estado per-hero, SIN clave serializada.
// OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.sync/G.syncServer NUNCA se crean ⇒ byte-id. nowArg permite al harness inyectar el reloj sin tocar Date.now real (prueba
// ventana/expiración + convergencia). Fallback al reloj inyectado (G.syncNow) para que el re-tick del game-loop no reintroduzca Date.now REAL entre frames (footgun heredado influx/frontier).
function tickBattleSync(nowArg){ if(!BATTLE_SYNC.enabled) return; const now=(nowArg!=null?+nowArg:(G.syncNow!=null?+G.syncNow:Date.now()));
  const src=G.syncServer||{}, count={}, windowMs=Math.max(1,(BATTLE_SYNC.windowSec|0))*1000;
  for(const z of (BATTLE_SYNC.zones||[])){ const marks=src[z]; if(!marks) continue;
    const c=syncCount(marks, now, windowMs); if(c>0) count[z]=c; }   // nº de sincronizados vigentes en la ventana (expira gestas viejas = decay determinista)
  G.sync={ count, nowMs:now }; }
// helper server-side: registra la GESTA (kill) de un jugador `id` en una zona marcando su último instante `atMs` (mirror del contador monótono h.kills; la ventana expira las viejas). Puro sobre G.syncServer.
function syncMark(zone, id, atMs){ if((BATTLE_SYNC.zones||[]).indexOf(zone)<0 || id==null) return null;
  const src=G.syncServer||(G.syncServer={}), m=src[zone]||(src[zone]={}); m[String(id)]=+atMs||0; return m; }
// glifo de la Sincronía para el badge (mirror influxTag/frontierTag): ⇌ (espadas cruzadas sincronizadas) si la zona del héroe está en Sincronía (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function syncTag(h){ h=h||G.hero; if(!BATTLE_SYNC.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(BATTLE_SYNC.zones||[]).indexOf(z)<0) return ""; return syncOpen(z) ? "⇌" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su nº de sincronizados LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function syncVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const syncable=!!(z && (BATTLE_SYNC.zones||[]).indexOf(z)>=0);
  const count=syncable?syncCountVal(z):0, tier=syncable?syncTier(count):0;
  return { enabled:!!BATTLE_SYNC.enabled, zone:z, syncable, count, tier, tierCount:(BATTLE_SYNC.tiers||[]).length,
    boostKind:BATTLE_SYNC.channel||"restedMult", boost: h?syncMul(h,BATTLE_SYNC.channel||"restedMult"):0 }; }

// CAS-2356: MARCHA / CONVOY MARCH — EVO #57, primer pilar VECTORIAL/DIRECCIONAL. Mide la COHERENCIA DIRECCIONAL de los vectores de VELOCIDAD de los jugadores en movimiento por zona
// (¿marchan JUNTOS con rumbo común?), ortogonal a headcount/footfall/composición/continuidad/dispersión/flujo/reloj (todos ESCALARES). server-authoritative: el server suma los vectores de
// velocidad de los presentes EN MOVIMIENTO, compara |Σv| contra Σ|v| ⇒ coherencia c∈[0,1]; mientras ≥minMovers se muevan con c≥cThreshold ACUMULA un `march` sostenido con DECAY, empuja
// { zona → { march, atMs } }; el cliente REFLEJA + PROYECTA al `now` compartido. convoyCoherence(vels,minSpeed) = CÓMPUTO server-side de la coherencia = { movers, c=|Σv|/Σ|v| }. Función PURA
// (0 RNG, 0 side-effect). Casos borde: todos QUIETOS (rapidez≤minSpeed) ⇒ movers 0/c 0 (NO abre); 2 en rumbos OPUESTOS ⇒ |Σv|≈0 ⇒ c≈0 (NO abre); N mismo rumbo ⇒ c=1 (abre si movers≥minMovers).
export function convoyCoherence(vels, minSpeed){ minSpeed=Math.max(0,+minSpeed||0);
  let sx=0, sy=0, sumSpeed=0, movers=0;
  if(Array.isArray(vels)) for(const v of vels){ if(!v) continue; const vx=+v.vx||0, vy=+v.vy||0, sp=Math.sqrt(vx*vx+vy*vy);
    if(sp<=minSpeed) continue; movers++; sx+=vx; sy+=vy; sumSpeed+=sp; }
  const c = sumSpeed>0 ? Math.sqrt(sx*sx+sy*sy)/sumSpeed : 0;
  return { movers, c: Math.max(0, Math.min(1, c)) }; }
// ¿el estado de movimiento de una zona SOSTIENE un convoy este tick? (movers≥minMovers Y c≥cThreshold). Puro sobre el resultado de convoyCoherence.
function convoySustains(co){ if(!co) return false; return (co.movers|0)>=(CONVOY_MARCH.minMovers|0) && (+co.c||0)>=(+CONVOY_MARCH.cThreshold||0); }
// convoyTier(march) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ march. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function convoyTier(march){ const T=CONVOY_MARCH.tiers||[]; march=+march||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && march>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost restedMult del tier vigente (0 si Tier 0). Puro. El gate global lo cubre convoyMul; aquí sólo la TABLA determinista.
function convoyBoost(march){ const t=convoyTier(march); return t>0 ? (+CONVOY_MARCH.tiers[t-1].boost||0) : 0; }
// `march` sostenido PROYECTADO de una zona leído del snapshot reflejado en G.convoy.march (ya proyectado al `now` por tickConvoy). 0 si sin snapshot / zona ausente. Puro.
function convoyMarchVal(zone){ const g=G.convoy; if(!g||!g.march||!zone) return 0; return +g.march[zone]||0; }
function convoyOpen(zone){ return convoyTier(convoyMarchVal(zone))>0; }
// convoyMul(h,kind) = el passive COMPARTIDO de los presentes en una zona en Marcha (tier≥1), en el canal restedMult (REUSA RESTED_XP), con PRECEDENCIA EXPLÍCITA anti-stacking
// (CONVOY_MARCH es la MÁS BAJA del canal, tras CAS-2355 BATTLE_SYNC ⇒ MÁXIMO ÚNICO): CEDE (return 0) a STANDINGS, MENTOR, SOUL, PULSE, CONGREGATION, WAYFARER, DIVERSE_COMPANY, LONG_WATCH, FRONTIER_SPREAD, INFLUX_SURGE y BATTLE_SYNC
// ⇒ se aplica el MAYOR (0 doble-dip). FELLOWSHIP(xpGain)/TERRITORY(safeRegen) ⊥ ⇒ coexisten. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function convoyMul(h,kind){ if(!CONVOY_MARCH.enabled||!h) return 0;
  if(kind!==(CONVOY_MARCH.channel||"restedMult")) return 0;
  if(standingsMul(h,kind)>0) return 0;   // precedencia MISMO-CANAL: STANDINGS (colectivo) gana ⇒ MARCHA cede
  if(mentorMul(h,kind)>0) return 0;      // MENTOR (personal) gana ⇒ cede
  if(soulMul(h,kind)>0) return 0;        // SOUL (recuperación) gana ⇒ cede
  if(pulseMul(h,kind)>0) return 0;       // PULSE (ambiental del reloj) gana ⇒ cede
  if(congMul(h,kind)>0) return 0;        // CONGREGATION (headcount) gana ⇒ cede
  if(wayfarerMul(h,kind)>0) return 0;    // WAYFARER (traversal) gana ⇒ cede
  if(confMul(h,kind)>0) return 0;        // DIVERSE_COMPANY (composición) gana ⇒ cede
  if(longWatchMul(h,kind)>0) return 0;   // LONG_WATCH (continuidad) gana ⇒ cede
  if(frontierMul(h,kind)>0) return 0;    // FRONTIER_SPREAD (dispersión) gana ⇒ cede
  if(influxMul(h,kind)>0) return 0;      // INFLUX_SURGE (afluencia) gana ⇒ cede
  if(syncMul(h,kind)>0) return 0;        // BATTLE_SYNC (sincronía) gana ⇒ cede (CONVOY_MARCH es la MÁS BAJA del canal, tras CAS-2355)
  const z=zoneOf(world,h.x,h.y); if(!z || (CONVOY_MARCH.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona de marcha ⇒ 0
  return convoyBoost(convoyMarchVal(z));   // el Δ del tier vigente por el `march` server-authoritative de esa zona
}
// tick de la MARCHA (mirror tickInflux/tickFrontier): REFLEJA el snapshot server-authoritative { zona → { march, atMs } } (empujado por el server, cacheado en G.convoyServer) y lo
// PROYECTA al `now` compartido hacia G.convoy.march aplicando el DECAY determinista por vida-media (march_now = march·0.5^(max(0,now−atMs)/halfLife), 0 RNG, techo capMarch). SIN estado
// per-hero, SIN clave serializada. OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.convoy/G.convoyServer NUNCA se crean ⇒ byte-id. nowArg permite al harness inyectar el reloj sin
// tocar Date.now real (prueba decay + convergencia). Fallback al reloj inyectado (G.convoyNow) para que el re-tick del game-loop no reintroduzca Date.now REAL (footgun heredado influx/frontier).
function tickConvoy(nowArg){ if(!CONVOY_MARCH.enabled) return; const now=(nowArg!=null?+nowArg:(G.convoyNow!=null?+G.convoyNow:Date.now()));
  const src=G.convoyServer||{}, march={}, hl=Math.max(1,(CONVOY_MARCH.halfLifeSec|0))*1000, cap=Math.max(0,(CONVOY_MARCH.capMarch|0));
  for(const z of (CONVOY_MARCH.zones||[])){ const raw=src[z]; if(!raw) continue;
    const base=Math.max(0,+raw.march||0), atMs=+raw.atMs||0, dtMs=Math.max(0,now-atMs);
    let m=base * Math.pow(0.5, dtMs/hl); if(cap>0) m=Math.min(cap,m);   // DECAE determinista por vida-media hacia el `now` compartido (0 RNG)
    if(m>0) march[z]=m; }
  G.convoy={ march, nowMs:now }; }
// helper server-side: ACUMULA `add` unidades de marcha en una zona sobre el `march` proyectado al `atMs` (mirror del acumulador con decay). Puro sobre G.convoyServer; devuelve el nuevo raw.
function convoyAccrue(zone, add, atMs){ if((CONVOY_MARCH.zones||[]).indexOf(zone)<0) return null; add=Math.max(0,+add||0);
  const src=G.convoyServer||(G.convoyServer={}), raw=src[zone], hl=Math.max(1,(CONVOY_MARCH.halfLifeSec|0))*1000;
  const prevBase=raw?Math.max(0,+raw.march||0):0, prevAt=raw?(+raw.atMs||0):atMs, dtMs=Math.max(0,atMs-prevAt);
  const projected=prevBase*Math.pow(0.5, dtMs/hl);   // proyecta el march previo al instante de esta acumulación
  src[zone]={ march:projected+add, atMs }; return src[zone]; }
// helper server-side: dado el estado de movimiento {vels} de una zona y el dt, computa la coherencia y ACUMULA accruePerSec·dt si el convoy se sostiene (movers≥K y c≥umbral), o SÓLO
// decae (add 0). Devuelve { co, add, raw }. Puro salvo la escritura en G.convoyServer (mismo patrón que influx transition). Prueba diferenciadores: quietos/opuestos ⇒ 0 ⇒ decae.
function convoyStep(zone, vels, dtSec, atMs){ if((CONVOY_MARCH.zones||[]).indexOf(zone)<0) return null;
  const co=convoyCoherence(vels, CONVOY_MARCH.minSpeed), add=convoySustains(co) ? (Math.max(0,+CONVOY_MARCH.accruePerSec||0)*Math.max(0,+dtSec||0)) : 0;
  const raw=convoyAccrue(zone, add, atMs); return { co, add, raw }; }
// glifo de la Marcha para el badge (mirror influxTag/frontierTag): ⇉ (flechas paralelas del convoy) si la zona del héroe está en Marcha (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function convoyTag(h){ h=h||G.hero; if(!CONVOY_MARCH.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(CONVOY_MARCH.zones||[]).indexOf(z)<0) return ""; return convoyOpen(z) ? "⇉" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su `march` sostenido LIVE server-authoritative, tier vigente y passive efectivo. 0 sim/RNG/side-effect.
export function convoyVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const convoyable=!!(z && (CONVOY_MARCH.zones||[]).indexOf(z)>=0);
  const march=convoyable?convoyMarchVal(z):0, tier=convoyable?convoyTier(march):0;
  return { enabled:!!CONVOY_MARCH.enabled, zone:z, convoyable, march:+march.toFixed(2), tier, tierCount:(CONVOY_MARCH.tiers||[]).length,
    boostKind:CONVOY_MARCH.channel||"restedMult", boost: h?convoyMul(h,CONVOY_MARCH.channel||"restedMult"):0 }; }

// ============================================================================
// CAS-2362: CORDÓN DE GUARDIA / WARDING RING (DARK, WARDING_RING) — EVO mecánica #59. Canal FRESCO wardRegen (regen de HP, ⊥ restedMult) + eje FRESCO COBERTURA ANGULAR (distribución
// de RUMBOS de las posiciones alrededor del centroide). server-authoritative: el server toma las posiciones de los presentes, calcula el centroide, cuenta cuántos SECTORES angulares
// distintos ocupan los del anillo (fuera de ringRadius) ⇒ cobertura∈[0,1]; mientras ≥minMembers logren cover≥coverThreshold ACUMULA un `ward` sostenido con DECAY, empuja { zona →
// { ward, atMs } }; el cliente REFLEJA + PROYECTA al `now` compartido. wardCoverage(positions) = CÓMPUTO server-side de la cobertura angular = { members, onRing, sectors, cover }. Función
// PURA (0 RNG, 0 side-effect). Casos borde: 1 jugador ⇒ centroide en él ⇒ onRing 0/cover 0 (NO abre); N AMONTONADOS (dentro de ringRadius) ⇒ onRing 0/cover 0 (NO abre, ≠ Congregación);
// N en LÍNEA ⇒ 2 sectores ⇒ cover baja (NO abre, ≠ Expedición área); N REPARTIDOS en rumbos ⇒ muchos sectores ⇒ cover alta (abre si onRing≥minMembers). Funciona con QUIETOS (≠ Convoy velocidad).
export function wardCoverage(positions){
  const S=Math.max(1,(WARDING_RING.sectors|0)||8), rMin=Math.max(0,+WARDING_RING.ringRadius||0);
  const pts=Array.isArray(positions)?positions.filter(p=>p && isFinite(+p.x) && isFinite(+p.y)):[];
  const members=pts.length;
  if(members===0) return { members:0, onRing:0, sectors:0, cover:0 };
  let sx=0, sy=0; for(const p of pts){ sx+=(+p.x); sy+=(+p.y); }
  const cx=sx/members, cy=sy/members;                                   // centroide = media de las posiciones presentes
  const occ={}; let occN=0, onRing=0;
  for(const p of pts){ const dx=(+p.x)-cx, dy=(+p.y)-cy, d=Math.sqrt(dx*dx+dy*dy);
    if(d<=rMin) continue;                                               // en el NÚCLEO (no define un rumbo) ⇒ no es parte del anillo (amontonamiento ⇒ onRing 0)
    onRing++;
    let a=Math.atan2(dy,dx); if(a<0) a+=2*Math.PI;                      // rumbo ∈ [0,2π)
    let s=Math.floor(a/((2*Math.PI)/S)); if(s>=S) s=S-1; if(s<0) s=0;   // sector angular
    if(!occ[s]){ occ[s]=1; occN++; } }
  const cover=occN/S;
  return { members, onRing, sectors:occN, cover: Math.max(0, Math.min(1, cover)) }; }
// ¿el estado de posición de una zona SOSTIENE un Cordón este tick? (onRing≥minMembers Y cover≥coverThreshold). Puro sobre el resultado de wardCoverage.
function wardSustains(wc){ if(!wc) return false; return (wc.onRing|0)>=(WARDING_RING.minMembers|0) && (+wc.cover||0)>=(+WARDING_RING.coverThreshold||0); }
// wardTier(ward) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ ward. Determinista, monótono, sin histéresis. OFF/sin tiers ⇒ 0.
function wardTier(ward){ const T=WARDING_RING.tiers||[]; ward=+ward||0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && ward>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost del canal wardRegen del tier vigente (0 si Tier 0). Puro. El gate global lo cubre wardMul; aquí sólo la TABLA determinista.
function wardBoost(ward){ const t=wardTier(ward); return t>0 ? (+WARDING_RING.tiers[t-1].boost||0) : 0; }
// `ward` sostenido PROYECTADO de una zona leído del snapshot reflejado en G.ward.ward (ya proyectado al `now` por tickWard). 0 si sin snapshot / zona ausente. Puro.
function wardVal(zone){ const g=G.ward; if(!g||!g.ward||!zone) return 0; return +g.ward[zone]||0; }
function wardOpen(zone){ return wardTier(wardVal(zone))>0; }
// wardMul(h,kind) = el passive COMPARTIDO de los presentes en una zona con Cordón (tier≥1), en el canal FRESCO wardRegen (regen de HP). PRECEDENCIA máximo-único DENTRO del canal:
// WARDING_RING es (por ahora) la ÚNICA fuente ⇒ máximo-único trivial (documentado para que futuras del arco de-stackeen aquí). ORTOGONAL a restedMult (seam gainXP) y a safeRegen
// (SAFEZONE/TERRITORY, kind distinto) ⇒ jamás dobla con NINGÚN canal previo. Puro (0 RNG/estado/side-effect). Gated ⇒ OFF ⇒ 0 (byte-id).
function wardMul(h,kind){ if(!WARDING_RING.enabled||!h) return 0;
  if(kind!==(WARDING_RING.channel||"wardRegen")) return 0;
  const z=zoneOf(world,h.x,h.y); if(!z || (WARDING_RING.zones||[]).indexOf(z)<0) return 0;   // el héroe NO está en una zona de cordón ⇒ 0
  return wardBoost(wardVal(z));   // el boost del tier vigente por el `ward` server-authoritative de esa zona
}
// tick del CORDÓN (mirror tickConvoy): REFLEJA el snapshot server-authoritative { zona → { ward, atMs } } (empujado por el server, cacheado en G.wardServer) y lo PROYECTA al `now`
// compartido hacia G.ward.ward aplicando el DECAY determinista por vida-media (ward_now = ward·0.5^(max(0,now−atMs)/halfLife), 0 RNG, techo capWard). SIN estado per-hero, SIN clave
// serializada. OFF ⇒ NUNCA se invoca (Date.now nunca se llama) ⇒ G.ward/G.wardServer NUNCA se crean ⇒ byte-id. nowArg permite al harness inyectar el reloj sin tocar Date.now real.
function tickWard(nowArg){ if(!WARDING_RING.enabled) return; const now=(nowArg!=null?+nowArg:(G.wardNow!=null?+G.wardNow:Date.now()));
  const src=G.wardServer||{}, ward={}, hl=Math.max(1,(WARDING_RING.halfLifeSec|0))*1000, cap=Math.max(0,(WARDING_RING.capWard|0));
  for(const z of (WARDING_RING.zones||[])){ const raw=src[z]; if(!raw) continue;
    const base=Math.max(0,+raw.ward||0), atMs=+raw.atMs||0, dtMs=Math.max(0,now-atMs);
    let w=base * Math.pow(0.5, dtMs/hl); if(cap>0) w=Math.min(cap,w);   // DECAE determinista por vida-media hacia el `now` compartido (0 RNG)
    if(w>0) ward[z]=w; }
  G.ward={ ward, nowMs:now }; }
// helper server-side: ACUMULA `add` unidades de cordón en una zona sobre el `ward` proyectado al `atMs` (mirror del acumulador con decay). Puro sobre G.wardServer; devuelve el nuevo raw.
function wardAccrue(zone, add, atMs){ if((WARDING_RING.zones||[]).indexOf(zone)<0) return null; add=Math.max(0,+add||0);
  const src=G.wardServer||(G.wardServer={}), raw=src[zone], hl=Math.max(1,(WARDING_RING.halfLifeSec|0))*1000;
  const prevBase=raw?Math.max(0,+raw.ward||0):0, prevAt=raw?(+raw.atMs||0):atMs, dtMs=Math.max(0,atMs-prevAt);
  const projected=prevBase*Math.pow(0.5, dtMs/hl);   // proyecta el ward previo al instante de esta acumulación
  src[zone]={ ward:projected+add, atMs }; return src[zone]; }
// helper server-side: dado el set de posiciones {x,y} de una zona y el dt, computa la cobertura angular y ACUMULA accruePerSec·dt si el Cordón se sostiene (onRing≥K y cover≥umbral),
// o SÓLO decae (add 0). Devuelve { wc, add, raw }. Puro salvo la escritura en G.wardServer (mismo patrón que convoyStep). Prueba diferenciadores: amontonados/línea/1-solo ⇒ 0 ⇒ decae.
function wardStep(zone, positions, dtSec, atMs){ if((WARDING_RING.zones||[]).indexOf(zone)<0) return null;
  const wc=wardCoverage(positions), add=wardSustains(wc) ? (Math.max(0,+WARDING_RING.accruePerSec||0)*Math.max(0,+dtSec||0)) : 0;
  const raw=wardAccrue(zone, add, atMs); return { wc, add, raw }; }
// glifo del Cordón para el badge (mirror convoyTag): ◯ (anillo de guardia) si la zona del héroe está en Cordón (tier≥1). Puro, 0 sim/RNG. "" si OFF / tier 0.
export function wardTag(h){ h=h||G.hero; if(!WARDING_RING.enabled||!h) return ""; const z=zoneOf(world,h.x,h.y);
  if(!z||(WARDING_RING.zones||[]).indexOf(z)<0) return ""; return wardOpen(z) ? "◯" : ""; }
// View-model PURO para el HUD/badge: la zona del héroe, su `ward` sostenido LIVE server-authoritative, tier vigente y passive efectivo (canal wardRegen). 0 sim/RNG/side-effect.
export function wardVM(h){ h=h||G.hero; const z=h?zoneOf(world,h.x,h.y):null;
  const wardable=!!(z && (WARDING_RING.zones||[]).indexOf(z)>=0);
  const ward=wardable?wardVal(z):0, tier=wardable?wardTier(ward):0;
  return { enabled:!!WARDING_RING.enabled, zone:z, wardable, ward:+ward.toFixed(2), tier, tierCount:(WARDING_RING.tiers||[]).length,
    boostKind:WARDING_RING.channel||"wardRegen", boost: h?wardMul(h,WARDING_RING.channel||"wardRegen"):0 }; }

// CAS-2409: ÚLTIMA RESISTENCIA / AGUANTE (DARK, LAST_STAND) — EVO mecánica #69. EJE FRESCO RATIO DE FUERZA / SUPERADO EN NÚMERO (local force-ratio) + canal REUSADO wardRegen (SHARE-CAP con Warding Ring #59).
// server-authoritative, 0-RNG, 0-timer, STATELESS. El conteo de "superado en número" = función PURA del estado de sim determinista (enemigos que te ENGANCHAN ahora) ⇒ MISMO ratio para todo observador ⇒ shard-consistente (0 desync).
// lastStandCount(h) = nº de enemigos ALIVE, NO-neutrales, en estado de ENGANCHE (chase/windup/strike/recover/shield — MISMO predicado que bonfireUnsafe: "en aggro persiguiendo/atacando") dentro de engageRadius del héroe.
// RATIO INSTANTÁNEO (⊥ Cadence meter-decayente): cuenta a QUIÉNES te enganchan AHORA, sin acumulador temporal. Puro (0 RNG/estado/reloj). OFF ⇒ nunca se llama (short-circuit en wardRegenBoost) ⇒ 0 coste, byte-id.
function lastStandCount(h){ h=h||G.hero; if(!h) return 0;
  const r=Math.max(0,+LAST_STAND.engageRadius||0), r2=r*r; let n=0;
  for(const e of G.enemies){ if(!e||e.dead||e.hp<=0) continue;
    if(e.tpl&&e.tpl.neutral&&!e.hostile) continue;               // neutrales pacíficos no enganchan ⇒ no cuentan (mismo criterio que la selección de aggro)
    const engaged=(e.state==="chase"||e.state==="windup"||e.state==="strike"||e.state==="recover"||e.state==="shield");
    if(!engaged) continue;                                        // sólo los que te ENGANCHAN (aggro activa sobre el héroe) — idle/patrulla/huida no cuentan
    if(r>0){ const dx=e.x-h.x, dy=e.y-h.y; if(dx*dx+dy*dy>r2) continue; }   // gate de PROXIMIDAD: enganchados pero lejos no "te rodean"
    n++; }
  return n; }
// lastStandTier(count) = índice del tier vigente (0 = sin efecto) = el más alto cuyo `min` ≤ conteo. Determinista, monótono por CONTEO (ratio instantáneo, NO permanencia per-pid). OFF/sin tiers ⇒ 0.
function lastStandTier(count){ const T=LAST_STAND.tiers||[]; count=count|0; let idx=0;
  for(let i=0;i<T.length;i++){ if(T[i] && count>=(+T[i].min||0)) idx=i+1; } return idx; }
// boost del canal wardRegen que aporta LAST_STAND para un conteo dado (0 si Tier 0). Puro. El gate global lo cubre lastStandMul/wardRegenBoost; aquí sólo la TABLA determinista.
function lastStandBoostFor(count){ const t=lastStandTier(count); return t>0 ? (+LAST_STAND.tiers[t-1].boost||0) : 0; }
// lastStandMul(h) = el boost del canal wardRegen aportado por estar SUPERADO EN NÚMERO. Gated ⇒ OFF ⇒ 0 (byte-id). Puro (0 RNG/estado/reloj/side-effect). ⊥ a restedMult/goldFind/oocMitigation/critChance/xpGain/vamp/lootQuality.
function lastStandMul(h){ if(!LAST_STAND.enabled||!h) return 0;
  if((LAST_STAND.channel||"wardRegen")!=="wardRegen") return 0;  // seguridad: LAST_STAND SÓLO alimenta el canal wardRegen (si el knob se re-apunta, no contribuye por defecto)
  return lastStandBoostFor(lastStandCount(h)); }
// wardRegenBoost(h) = boost EFECTIVO del canal wardRegen en el seam wardRegenTick, UNIFICANDO Warding Ring #59 + Last Stand #69 por SHARE-CAP: boost combinado = min(lastStandWardCap, wardBoost + lastStandBoost) ⇒ 0
// doble-dip más allá del techo (mismo patrón que Tempest lootQuality vs Trailcraft y Cadence critChance vs Delve). BYTE-NEUTRO: con LAST_STAND OFF DEVUELVE wardMul() tal cual (idéntico al seam LIVE de Warding Ring ⇒ 0-regr). Puro.
function wardRegenBoost(h){ const wr=wardMul(h,WARDING_RING.channel||"wardRegen");   // contribuyente WARDING_RING (0 si OFF / fuera de zona de cordón)
  if(!LAST_STAND.enabled) return wr;                                                  // LAST_STAND OFF ⇒ ruta byte-IDÉNTICA al LIVE de Warding Ring (delegación pura, 0 iteración de G.enemies)
  const ls=lastStandMul(h); if(ls<=0) return wr;                                      // no superado en número ⇒ sin cambio (sólo el aporte de Warding Ring)
  const cap=Math.max(0,+LAST_STAND.lastStandWardCap||0);
  return Math.min(cap, wr+ls); }                                                      // SHARE-CAP: boost combinado capado ⇒ 0 doble-dip (con Warding a tope 0.15 ⇒ ya en el techo ⇒ Last Stand no añade)
// glifo de ÚLTIMA RESISTENCIA para el badge (mirror wardTag/tempestTag): ⚔ (superado en número) si el héroe está enganchado por ≥ umbral de enemigos (tier≥1). Puro, 0 sim/RNG. "" si OFF / no superado.
export function lastStandTag(h){ h=h||G.hero; if(!LAST_STAND.enabled||!h) return "";
  return lastStandTier(lastStandCount(h))>0 ? "⚔" : ""; }
// View-model PURO para el HUD/badge: el conteo de enganchados server-authoritative, el tier vigente, el boost de Last Stand y el boost wardRegen EFECTIVO (unificado con Warding Ring por share-cap). 0 sim/RNG/side-effect.
export function lastStandVM(h){ h=h||G.hero;
  const count=(LAST_STAND.enabled&&h)?lastStandCount(h):0;
  const tier=lastStandTier(count), boost=(LAST_STAND.enabled&&h)?lastStandBoostFor(count):0;
  const wr=h?wardMul(h,WARDING_RING.channel||"wardRegen"):0;     // contribuyente Warding Ring (para exponer el de-stack)
  const cap=Math.max(0,+LAST_STAND.lastStandWardCap||0);
  const combined=(LAST_STAND.enabled&&boost>0)?Math.min(cap, wr+boost):wr;   // boost wardRegen EFECTIVO (share-cap)
  return { enabled:!!LAST_STAND.enabled, channel:LAST_STAND.channel||"wardRegen", engageRadius:+LAST_STAND.engageRadius||0,
    threshold:(LAST_STAND.tiers&&LAST_STAND.tiers[0]?(LAST_STAND.tiers[0].min|0):0),
    count, tier, tierCount:(LAST_STAND.tiers||[]).length, boost:+boost.toFixed(4),
    wardBoost:+wr.toFixed(4), cap:+cap.toFixed(4), combinedBoost:+combined.toFixed(4),
    regenPct:+WARDING_RING.regenPct||0, regenRate:+((Math.max(0,+WARDING_RING.regenPct||0))*(1+combined)).toFixed(5),
    tag: lastStandTag(h) }; }

// CAS-2415: TERRENO FIRME / PISADA FIRME (DARK, FIRM_FOOTING) — EVO mecánica #70. EJE FRESCO ESPACIAL: el MATERIAL de terreno server-auth del tile bajo el héroe (world.terr) + canal FRESCO atkspd (bajo el techo global ATKSPD_TOTAL_CAP ⇒ share-cap/de-stack automático). ⊥ a las 11 LIVE #59-#69.
// heroTerr(h) = el material (T_*) del tile bajo el héroe, LEÍDO del world.terr server-auth (mismo array que solidBlocked/worldFingerprint). PURO (0 RNG/estado/side-effect). Fuera de mapa / sin world ⇒ -1 (⇒ Tier 0). Determinista ⇒ mismo material para todo observador del mismo snapshot.
function heroTerr(h){ h=h||G.hero; if(!h||!world||!world.terr) return -1;
  const tx=Math.floor(h.x/TS), ty=Math.floor(h.y/TS);
  if(tx<0||ty<0||tx>=MAP_W||ty>=MAP_H) return -1;
  return world.terr[ty*MAP_W+tx]|0; }
// firmFootingTier(terr) = índice del tier vigente (0 = sin ventaja) = el MÁS ALTO cuya lista `terr` contiene el material. LUT determinista pura. Material no listado (arena/agua/hielo/pantano/caldera) ⇒ 0.
function firmFootingTier(terr){ const T=FIRM_FOOTING.tiers||[]; terr=terr|0;
  for(let i=T.length-1;i>=0;i--){ const arr=T[i]&&T[i].terr; if(Array.isArray(arr)&&arr.indexOf(terr)>=0) return i+1; } return 0; }
// atkspd (puntos aditivos) que aporta el tier vigente para un material dado (0 si Tier 0), acotado por el sub-cap propio firmFootingCap. Puro (el gate global lo cubre firmFootingAtkspd/heroAtkspd; aquí sólo la TABLA determinista).
function firmFootingAtkFor(terr){ const t=firmFootingTier(terr); if(t<=0) return 0;
  const raw=+FIRM_FOOTING.tiers[t-1].atkspd||0, cap=Math.max(0,+FIRM_FOOTING.firmFootingCap||0);
  return raw>cap?cap:raw; }
// firmFootingAtkspd(h) = el bono de atkspd que aporta estar sobre TERRENO FIRME. Gated ⇒ OFF ⇒ 0 (byte-id: +0 en heroAtkspd). Puro (0 RNG/estado/reloj/side-effect). ⊥ a wardRegen/goldFind/oocMitigation/critChance/xpGain/vamp/lootQuality/restedMult.
function firmFootingAtkspd(h){ if(!FIRM_FOOTING.enabled||!h) return 0;
  if((FIRM_FOOTING.channel||"atkspd")!=="atkspd") return 0;   // seguridad: FIRM_FOOTING SÓLO alimenta el canal atkspd (si el knob se re-apunta, no contribuye por defecto)
  return firmFootingAtkFor(heroTerr(h)); }
export function firmFootingTag(h){ h=h||G.hero; if(!FIRM_FOOTING.enabled||!h) return "";
  return firmFootingTier(heroTerr(h))>0 ? "⛰" : ""; }
// View-model PURO para el HUD/badge: el material server-auth bajo el héroe, el tier vigente, el bono de atkspd de FIRM_FOOTING, la atkspd TOTAL (capada) y el techo. 0 sim/RNG/side-effect.
export function firmFootingVM(h){ h=h||G.hero;
  const terr=(FIRM_FOOTING.enabled&&h)?heroTerr(h):-1;
  const tier=(FIRM_FOOTING.enabled&&h)?firmFootingTier(terr):0;
  const bonus=(FIRM_FOOTING.enabled&&h)?firmFootingAtkFor(terr):0;
  const total=h?heroAtkspd(h):0;   // atkspd EFECTIVA (Σ fuentes, clamped a ATKSPD_TOTAL_CAP) — expone el share-cap global
  return { enabled:!!FIRM_FOOTING.enabled, channel:FIRM_FOOTING.channel||"atkspd",
    terr, tier, tierCount:(FIRM_FOOTING.tiers||[]).length, bonus:+bonus,
    cap:Math.max(0,+FIRM_FOOTING.firmFootingCap||0), atkspdTotal:+total, atkspdCap:ATKSPD_TOTAL_CAP,
    tag: firmFootingTag(h) }; }

// CAS-2426: ACECHO / SIGILO (SHADOW_STALK) — EJE SIGILO/LÍNEA-DE-VISIÓN + canal FRESCO detectRadius (radio de detección del mob). Funciones PURAS, deterministas, 0-RNG/0-timer/STATELESS, server-auth.
// stealthStalkOccluders(ax,ay,bx,by) = nº de tiles OCLUSORES (world.wallSet ∪ world.blockSet) que la línea de grid (raycast Bresenham) de (ax,ay) a (bx,by) atraviesa, EXCLUYENDO los tiles-extremo (donde están las entidades). = "espesor de cobertura" entre mob y héroe. PURO: función de world.wallSet/blockSet + coords (0 RNG/estado/side-effect). Fuera de mundo / sin sets ⇒ 0 (LOS despejada). Determinista ⇒ MISMO conteo para todo observador del mismo snapshot.
function stealthStalkOccluders(ax,ay,bx,by){ if(!world||(!world.wallSet&&!world.blockSet)) return 0;
  const sx0=Math.floor(ax/TS), sy0=Math.floor(ay/TS), tx1=Math.floor(bx/TS), ty1=Math.floor(by/TS);
  let tx=sx0, ty=sy0; const dx=Math.abs(tx1-tx), dy=Math.abs(ty1-ty), stepx=tx<tx1?1:-1, stepy=ty<ty1?1:-1;
  let err=dx-dy, occ=0, guard=0;
  const ws=world.wallSet, bs=world.blockSet;
  while(guard++<1024){
    const isEnd=(tx===sx0&&ty===sy0)||(tx===tx1&&ty===ty1);   // los tiles-extremo (mob/héroe) NO cuentan — sólo cobertura ENTRE ellos
    if(!isEnd && tx>=0&&ty>=0&&tx<MAP_W&&ty<MAP_H){ const idx=ty*MAP_W+tx; if((ws&&ws.has(idx))||(bs&&bs.has(idx))) occ++; }
    if(tx===tx1&&ty===ty1) break;
    const e2=2*err; if(e2>-dy){ err-=dy; tx+=stepx; } if(e2<dx){ err+=dx; ty+=stepy; }
  }
  return occ; }
// stealthStalkTier(occ) = índice del tier de OCULTAMIENTO vigente (0 = LOS despejada / sin ventaja) = el MÁS ALTO cuya `min` de oclusores se alcanza. LUT determinista pura.
function stealthStalkTier(occ){ const T=SHADOW_STALK.tiers||[]; occ=occ|0;
  let t=0; for(let i=0;i<T.length;i++){ if(occ>=(T[i].min|0)) t=i+1; } return t; }
// stealthStalkMit(ax,ay,bx,by) = fracción de reducción del radio de detección que gana el héroe por estar OCULTO de (ax,ay) [mob] — acotada por el sub-cap propio stealthStalkCap. 0 si LOS despejada. PURO (0 RNG/estado). NO gateado por enabled (los gates viven en el seam/VM).
function stealthStalkMit(ax,ay,bx,by){ const occ=stealthStalkOccluders(ax,ay,bx,by); const t=stealthStalkTier(occ); if(t<=0) return 0;
  const raw=+SHADOW_STALK.tiers[t-1].mit||0, cap=Math.max(0,+SHADOW_STALK.stealthStalkCap||0);
  return raw>cap?cap:raw; }
// stealthStalkAggro(aggroBase,e,h,d) = el radio de detección/adquisición EFECTIVO del mob `e` hacia el héroe `h`. Gated ⇒ OFF ⇒ aggroBase EXACTO (byte-id: máquina de estados del enemigo idéntica al HEAD; el raycast NUNCA corre). Si el héroe está más lejos que el radio base ⇒ aggroBase (concealment irrelevante, 0 raycast — sólo perf). Si LOS despejada ⇒ aggroBase. Si oculto ⇒ aggroBase*(1-mit). PURO/determinista.
function stealthStalkAggro(aggroBase,e,h,d){ if(!SHADOW_STALK.enabled||!e||!h) return aggroBase;
  if((SHADOW_STALK.channel||"detectRadius")!=="detectRadius") return aggroBase;   // seguridad: SHADOW_STALK SÓLO alimenta detectRadius (si el knob se re-apunta, no contribuye)
  if(d>=aggroBase) return aggroBase;   // fuera del radio base ⇒ no adquiriría igual ⇒ 0 raycast (perf, behavior-idéntico para la adquisición)
  const mit=stealthStalkMit(e.x,e.y,h.x,h.y); if(mit<=0) return aggroBase;
  return aggroBase*(1-mit); }
// glifo del badge: "" si OFF/LOS-despejada, 🌒 si el héroe está OCULTO de AL MENOS un mob vivo dentro de su radio base. PURO lectura (0 sim/RNG). Cosmético.
export function shadowStalkTag(h){ h=h||G.hero; if(!SHADOW_STALK.enabled||!h) return "";
  return shadowStalkBestTier(h)>0 ? "🌒" : ""; }
// shadowStalkBestTier(h) = el tier de ocultamiento MÁS ALTO que el héroe tiene frente a CUALQUIER mob vivo (no-neutral) dentro de su radio base de aggro. = "cuán oculto estás del cazador más cercano que podría verte". PURO. 0 si OFF / a la vista de todos / sin mobs cerca.
function shadowStalkBestTier(h){ h=h||G.hero; if(!SHADOW_STALK.enabled||!h||!G.enemies) return 0;
  let best=0; for(const e of G.enemies){ if(!e||e.dead||e.hp<=0) continue; if(e.tpl&&e.tpl.neutral&&!e.hostile) continue;
    const aggroBase=e.hostile?300:(e.tpl?e.tpl.aggro:0); const d=Math.hypot(h.x-e.x,h.y-e.y); if(d>=aggroBase) continue;
    const t=stealthStalkTier(stealthStalkOccluders(e.x,e.y,h.x,h.y)); if(t>best) best=t; }
  return best; }
// View-model PURO para el HUD/badge: el mejor tier de ocultamiento vigente, la mitigación efectiva, el sub-cap y el radio base del cazador más cercano. 0 sim/RNG/side-effect.
export function shadowStalkVM(h){ h=h||G.hero; const on=!!SHADOW_STALK.enabled&&!!h;
  const tier=on?shadowStalkBestTier(h):0;
  // mit efectiva del cazador que da el mejor tier (para el HUD) — re-derivado del mismo predicado
  let mit=0, hunterAggro=0, hunterD=0;
  if(on&&G.enemies){ let best=0; for(const e of G.enemies){ if(!e||e.dead||e.hp<=0) continue; if(e.tpl&&e.tpl.neutral&&!e.hostile) continue;
      const ab=e.hostile?300:(e.tpl?e.tpl.aggro:0); const d=Math.hypot(h.x-e.x,h.y-e.y); if(d>=ab) continue;
      const t=stealthStalkTier(stealthStalkOccluders(e.x,e.y,h.x,h.y)); if(t>best){ best=t; mit=stealthStalkMit(e.x,e.y,h.x,h.y); hunterAggro=ab; hunterD=d; } } }
  return { enabled:!!SHADOW_STALK.enabled, channel:SHADOW_STALK.channel||"detectRadius",
    tier, tierCount:(SHADOW_STALK.tiers||[]).length, mit:+mit.toFixed(4),
    cap:Math.max(0,+SHADOW_STALK.stealthStalkCap||0),
    hunterAggro:+hunterAggro, hunterAggroEff:+(hunterAggro*(1-mit)).toFixed(2), hunterDist:+hunterD.toFixed(2),
    tag: shadowStalkTag(h) }; }

// CAS-2432: PRESIÓN POR ESCASEZ DE RECURSOS (SCARCITY_EDGE) — EJE ESCASEZ/AGOTAMIENTO del mundo compartido + canal FRESCO essenceFind (multiplicador de recompensa de esencia por forrajeo). Funciones PURAS, deterministas, 0-RNG/0-timer/STATELESS, server-auth.
// scarcityZoneCap(zone) = Σ sp.max sobre los spawners de la ZONA = capacidad de spawn autoritativa de esa zona. PURO (lectura de world.spawners). 0 si la zona no tiene spawners (ciudad/field).
function scarcityZoneCap(zone){ let cap=0; for(const s of (world&&world.spawners||[])){ if(!s||s.zone!==zone) continue; cap+=(s.max|0); } return cap; }
// scarcityZoneAlive(zone) = nº de mobs VIVOS no-jefe cuya posición cae en la ZONA. Cuenta el estado de sim replicado (posiciones deterministas). Excluye jefes (la escasez es de mobs de forrajeo, no del jefe) y neutrales. PURO.
function scarcityZoneAlive(zone){ let n=0; for(const e of (G.enemies||[])){ if(!e||e.dead||e.hp<=0||e.isBoss) continue; if(e.tpl&&e.tpl.neutral&&!e.hostile) continue; if(zoneOf(world,e.x,e.y)===zone) n++; } return n; }
// scarcityDepletion(zone) = fracción de la capacidad de spawn de la zona actualmente VACÍA = 1 - vivos/cap ∈ [0,1]. Cap < minZoneCap ⇒ 0 (zonas de cap ínfimo no cuentan). PURO/determinista ⇒ MISMO valor para todo observador del mismo snapshot.
function scarcityDepletion(zone){ const cap=scarcityZoneCap(zone); if(cap < Math.max(1,SCARCITY_EDGE.minZoneCap|0)) return 0;
  const alive=scarcityZoneAlive(zone); const dep=1-alive/cap; return dep<0?0:(dep>1?1:dep); }
// scarcityTier(dep) = índice del tier de agotamiento vigente (0 = zona rica / sin ventaja) = el MÁS ALTO cuya `min` de agotamiento se alcanza. LUT determinista pura.
function scarcityTier(dep){ const T=SCARCITY_EDGE.tiers||[]; let t=0; for(let i=0;i<T.length;i++){ if(dep>=(+T[i].min||0)) t=i+1; } return t; }
// scarcityMul(zone) = fracción del xp del mob concedida como esencia de forrajeo, acotada por el sub-cap propio scarcityEssCap. Gated ⇒ OFF ⇒ 0 EXACTO (byte-neutral). PURO (0 RNG/estado). NO gateado internamente salvo enabled (el seam decide dónde aplica).
function scarcityMul(zone){ if(!SCARCITY_EDGE.enabled) return 0;
  if((SCARCITY_EDGE.channel||"essenceFind")!=="essenceFind") return 0;   // seguridad: SCARCITY_EDGE SÓLO alimenta essenceFind (si el knob se re-apunta, no contribuye)
  const dep=scarcityDepletion(zone); const t=scarcityTier(dep); if(t<=0) return 0;
  const raw=+SCARCITY_EDGE.tiers[t-1].mul||0, cap=Math.max(0,+SCARCITY_EDGE.scarcityEssCap||0);
  return cap>0 ? Math.min(cap, raw) : raw; }
// scarcityForageEssence(zone, tpl) = la esencia de forrajeo por un kill en la zona = round(scarcityMul(zone) * tpl.xp). El xp del mob = proxy determinista de su "valor". 0 si OFF / zona rica / sin xp. PURO — el seam decide banca a meta.
function scarcityForageEssence(zone, tpl){ if(!SCARCITY_EDGE.enabled||!tpl) return 0; const mul=scarcityMul(zone); if(mul<=0) return 0;
  const xp=+tpl.xp||0; return Math.round(mul*xp); }
// scarcityTag(h) = glifo del badge de ESCASEZ (⧗) si el héroe está en una zona AGOTADA (tier>0). PURO. "" si OFF / zona rica / sin zona.
export function scarcityTag(h){ h=h||G.hero; if(!SCARCITY_EDGE.enabled||!h) return "";
  return scarcityTier(scarcityDepletion(zoneOf(world,h.x,h.y)))>0 ? "⧗" : ""; }
// View-model PURO para el HUD/badge: el tier de agotamiento de la zona del héroe, la depletion, el mul efectivo, el sub-cap, cap/vivos de la zona. 0 sim/RNG/side-effect.
export function scarcityVM(h){ h=h||G.hero; const on=!!SCARCITY_EDGE.enabled&&!!h;
  const zone=h?zoneOf(world,h.x,h.y):null;
  const cap=on?scarcityZoneCap(zone):0, alive=on?scarcityZoneAlive(zone):0;
  const dep=on?scarcityDepletion(zone):0, tier=on?scarcityTier(dep):0, mul=on?scarcityMul(zone):0;
  return { enabled:!!SCARCITY_EDGE.enabled, channel:SCARCITY_EDGE.channel||"essenceFind",
    zone, zoneCap:+cap, zoneAlive:+alive, depletion:+dep.toFixed(4),
    tier, tierCount:(SCARCITY_EDGE.tiers||[]).length, mul:+mul.toFixed(4),
    cap:Math.max(0,+SCARCITY_EDGE.scarcityEssCap||0), minZoneCap:Math.max(1,SCARCITY_EDGE.minZoneCap|0),
    tag: scarcityTag(h) }; }

// CAS-2439: PROXIMIDAD A AMENAZA APEX (APEX_PROXIMITY) — EJE PROXIMIDAD A UN DEPREDADOR APEX + canal FRESCO matFind (multiplicador de recompensa de MENA/forja por forrajeo cerca de un apex). Funciones PURAS, deterministas, 0-RNG/0-timer/STATELESS, server-auth.
// apexIsThreat(e) = ¿es un apex VIVO (jefe/campeón/campeón-élite)? Excluye muertos, neutrales y trash. PURO (lectura de flags de sim replicadas). El apex ya muerto (e.dead) NO cuenta ⇒ matar al apex no se auto-recompensa.
function apexIsThreat(e){ return !!(e && !e.dead && (e.hp>0) && (e.isBoss||e.champion||e.champElite)); }
// apexNearestDist(h) = distancia (px) al apex VIVO más cercano a la posición del héroe. ∞ si no hay apex vivo. PURO/determinista ⇒ MISMO valor para todo observador del mismo snapshot (posiciones = estado de sim replicado). Vecindad = todo G.enemies (el min ya selecciona el más cercano).
function apexNearestDist(h){ h=h||G.hero; if(!h) return Infinity; let best=Infinity;
  for(const e of (G.enemies||[])){ if(!apexIsThreat(e)) continue; const d=Math.hypot(h.x-e.x,h.y-e.y); if(d<best) best=d; } return best; }
// apexTier(dist) = índice del tier de proximidad vigente (0 = sin apex cerca / sin ventaja) = el MÁS PELIGROSO (menor `max`) cuya distancia se satisface. CERCA = tier ALTO. LUT determinista pura.
function apexTier(dist){ const T=APEX_PROXIMITY.tiers||[]; let t=0; for(let i=0;i<T.length;i++){ if(dist<=(+T[i].max||0)) t=i+1; } return t; }
// apexMatBonus(dist) = nº de mena de forrajeo del tier vigente, acotado por el sub-cap propio apexMatCap. Gated ⇒ OFF ⇒ 0 EXACTO (byte-neutral). PURO (0 RNG/estado). Seguridad de canal: sólo alimenta matFind.
function apexMatBonus(dist){ if(!APEX_PROXIMITY.enabled) return 0;
  if((APEX_PROXIMITY.channel||"matFind")!=="matFind") return 0;   // seguridad: APEX_PROXIMITY SÓLO alimenta matFind (si el knob se re-apunta, no contribuye)
  const t=apexTier(dist); if(t<=0) return 0;
  const raw=+APEX_PROXIMITY.tiers[t-1].mats||0, cap=Math.max(0,APEX_PROXIMITY.apexMatCap|0);
  return cap>0 ? Math.min(cap, raw) : raw; }
// apexForageMats(h, tpl) = la mena de forrajeo por un kill con un apex vivo cerca del héroe = apexMatBonus(distNearest). 0 si OFF / sin apex cerca / sin tpl. PURO — el seam decide banca a h.mats vía grantMats.
function apexForageMats(h, tpl){ if(!APEX_PROXIMITY.enabled||!tpl) return 0; return apexMatBonus(apexNearestDist(h||G.hero)); }
// apexTag(h) = glifo del badge de AMENAZA APEX (▲) si el héroe tiene un apex vivo dentro del radio de amenaza (tier>0). PURO. "" si OFF / sin apex cerca.
export function apexTag(h){ h=h||G.hero; if(!APEX_PROXIMITY.enabled||!h) return "";
  return apexTier(apexNearestDist(h))>0 ? "▲" : ""; }
// View-model PURO para el HUD/badge: el tier de proximidad, la distancia al apex, la mena efectiva por kill, el sub-cap. 0 sim/RNG/side-effect.
export function apexVM(h){ h=h||G.hero; const on=!!APEX_PROXIMITY.enabled&&!!h;
  const dist=on?apexNearestDist(h):Infinity, tier=on?apexTier(dist):0, mats=on?apexMatBonus(dist):0;
  return { enabled:!!APEX_PROXIMITY.enabled, channel:APEX_PROXIMITY.channel||"matFind",
    dist:(dist===Infinity?-1:+dist.toFixed(1)),
    tier, tierCount:(APEX_PROXIMITY.tiers||[]).length, mats:+mats,
    cap:Math.max(0,APEX_PROXIMITY.apexMatCap|0),
    tag: apexTag(h) }; }

// CAS-2445: PELIGRO POR AFIJO DE MOB (MOB_AFFIX_DANGER) — EJE CALIDAD/PELIGRO DE AFIJO DE MOB + canal FRESCO flaskPotency (recompensa de cargas de Estus por forrajeo amid-danger). Funciones PURAS, deterministas, 0-RNG/0-timer/STATELESS, server-auth. Los afijos (e.affix/e.affixes) = estado de sim REPLICADO asignado determinista al spawn (maybeAffix/spawnChampion, off-srand).
// affixDangerWeight(e) = peso de peligro total de un mob VIVO = Σ affixWeights[id] sobre mobAffixes(e) (campeón→2 afijos, trash afijado→1, boss/neutral→0; los boss NO llevan afijo — maybeAffix los excluye ⇒ ⊥ #73 apex). PURO (lectura de e.affix/e.affixes replicados). Muerto/sin hp ⇒ 0.
function affixDangerWeight(e){ if(!e||e.dead||!(e.hp>0)) return 0; const W=MOB_AFFIX_DANGER.affixWeights||{}; let s=0;
  for(const id of mobAffixes(e)){ s += (+W[id]||1); } return s; }
// affixDangerScore(h) = suma del peso de peligro de TODOS los mobs afijados VIVOS dentro de MOB_AFFIX_DANGER.radius del héroe. PURO/determinista ⇒ MISMO valor para todo observador del mismo snapshot (afijos+posiciones = estado replicado). 0 si no hay afijos cerca. Vecindad = radio (⊥ apex que mide distancia a UN jefe).
function affixDangerScore(h){ h=h||G.hero; if(!h) return 0; const R=+MOB_AFFIX_DANGER.radius||0, R2=R*R; let s=0;
  for(const e of (G.enemies||[])){ const w=affixDangerWeight(e); if(w<=0) continue; const dx=h.x-e.x, dy=h.y-e.y; if(dx*dx+dy*dy<=R2) s+=w; } return s; }
// affixDangerTier(score) = índice del tier de peligro vigente (0 = sin afijos cerca / sin ventaja) = el MÁS PELIGROSO (mayor `min`) cuyo score se satisface. MÁS peligro = tier ALTO. LUT determinista pura.
