  staminaMeta(){ return { enabled:STAMINA.enabled, max:STAMINA.max, regen:STAMINA.regen, regenDelay:STAMINA.regenDelay, flashS:STAMINA.flashS, cost:Object.assign({},STAMINA.cost) }; },
